CPC_QUESTIONS.push(...[{"id":"fcc-cpc-3079818","sourceQuestionId":"3079818","t":"cpc-m07","moduleId":"cpc-m07","q":"Em ação movida contra o Estado Sigma e o Município Zeta por cidadão que busca tratamento não previsto no âmbito do Sistema Unico de Saúde, o Juiz proferiu sentença que acolheu o pedido, mesmo ato por meio do qual concedeu tutela provisória de urgência. A sentença, além disso, determinou a intimação dos réus por Oficial de Justiça, sendo o Estado intimado no dia 18 de maio e o Município, no dia 19 de maio, por mandados juntados aos autos, respectivamente, nos dias 25 e 26 do mesmo mês, admitindo-se que em todos esses dias houve expediente forense. Isto considerado, o prazo para o Estado interpor recurso contra a sentença","o":["poderá ser dilatado, para além do dobro legal, se assim avençado com o litisconsorte passivo.","será contado da última data de intimação dos réus.","será contado da data da intimação do próprio Estado.","será contado da data da juntada aos autos do mandado de intimação do Estado.","será contado da data da juntada do último mandado de intimação cumprido."],"a":3,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079818","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Dos Prazos (arts. 218 a 235)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079818","year":2024,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488264","sourceQuestionId":"2488264","t":"cpc-m07","moduleId":"cpc-m07","q":"De acordo com o Código de Processo Civil, os atos processuais","o":["não podem ser objeto de nenhuma convenção, ainda que recaiam sobre direitos que admitam autocomposição.","processam-se, em regra, em segredo de justiça, mas podem ser acessados por terceiro que demonstrar legitimo interesse.","são públicos, tramitando em segredo de justiça apenas excepcionalmente.","poderão ser praticados apenas até as 20 horas, ainda que se processem na forma eletrônica ou que seu adiamento prejudique a diligência.","serão praticados, em regra, nas férias forenses."],"a":2,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488264","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Forma dos Atos Processuais (arts. 188 a 211)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488264","year":2025,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3571733","sourceQuestionId":"3571733","t":"cpc-m07","moduleId":"cpc-m07","q":"De acordo com o Código de Processo Civil, as citações, intimações e penhoras","o":["poderão ser realizadas nos feriados independentemente de autorização judicial.","não poderão ser realizadas nos feriados.","poderão ser realizadas nos feriados somente se houver prévia autorização judicial.","poderão ser realizadas nos feriados desde que haja autorização judicial, que poderá ser concedida mesmo depois de praticado o ato.","poderão ser realizadas nos feriados independentemente de autorização judicial somente quando absolutamente indispensáveis para evitar dano irreparável ou de difícil reparação."],"a":0,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025 • TEC 3571733","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Do Tempo e Do Lugar dos Atos Processuais (arts. 212 a 217)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3571733","year":2025,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1994872","sourceQuestionId":"1994872","t":"cpc-m07","moduleId":"cpc-m07","q":"No tocante aos prazos para a prática de atos processuais, estabelecidos pelo CPC:","o":["Na contagem de prazo em dias, estabelecido em lei ou pelo juiz, computar-se-ão somente os dias úteis.","O cômputo em dias úteis se aplica aos prazos convencionados em acordo ou transação firmado entre as partes processuais.","Na contagem de prazo em dias, estabelecido em lei ou pelo juiz, computar-se-ão os dias de forma contínua.","Na contagem do prazo computar-se-á o dia do começo, se for dia útil.","Será aplicado o cômputo de dias contínuos se não houver feriado."],"a":0,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE PE)/MPE PE/2022 • TEC 1994872","source":"FCC - Prom Jus (MPE PE)/MPE PE/2022","subject":"Direito Processual Civil - Dos Prazos (arts. 218 a 235)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1994872","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2340149","sourceQuestionId":"2340149","t":"cpc-m07","moduleId":"cpc-m07","q":"De acordo com o Código de Processo Civil, é lícito às partes plenamente capazes estipularem mudanças no procedimento para ajustá-lo às especificidades da causa e convencionar sobre os seus ônus, poderes, faculdades e deveres processuais,","o":["somente durante o processo, e desde que este verse sobre direitos que admitam autocomposição.","somente antes do processo, e desde que este verse sobre direitos que admitam autocomposição.","antes ou durante o processo, e desde que este verse sobre direitos que admitam autocomposição.","somente antes do processo, inclusive se este versar sobre direitos que não admitam autocomposição.","somente durante o processo, inclusive se este versar sobre direitos que não admitam autocomposição."],"a":2,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT18/TRT 18/Judiciária/Oficial de Justiça Avaliador Federal/2023 • TEC 2340149","source":"FCC - AJ TRT18/TRT 18/Judiciária/Oficial de Justiça Avaliador Federal/2023","subject":"Direito Processual Civil - Da Forma dos Atos Processuais (arts. 188 a 211)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2340149","year":2023,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1009449","sourceQuestionId":"1009449","t":"cpc-m07","moduleId":"cpc-m07","q":"Em relação à forma, ao tempo e ao lugar dos atos processuais, considere: I. Em regra, os atos e os termos processuais dependem de forma determinada, salvo quando a lei não a exigir, considerando-se válidos os atos realizados com essa obediência formal. II. Versando o processo sobre direitos que admitam autocomposição, é lícito às partes plenamente capazes estipular mudanças no procedimento para ajustá-lo às especificidades da causa e convencionar sobre os seus ônus, poderes, faculdades e deveres processuais, antes ou durante o processo. III. Os atos das partes consistentes em declarações unilaterais ou bilaterais de vontade produzem imediatamente a constituição, modificação ou extinção de direitos processuais, inclusive no tocante à desistência da ação. IV. Além dos declarados em lei, são feriados, para efeito forense, os sábados, os domingos e os dias em que não haja expediente forense. V. Os atos processuais realizar-se-ão ordinariamente na sede do juízo, ou, excepcionalmente, em outro lugar, em razão de deferência, de interesse da justiça, da natureza do ato ou de obstáculo arguido pelo interessado e acolhido pelo juiz. Está correto o que consta APENAS em","o":["II, IV e V.","II, III e V.","I, III e IV.","I, II e III.","III, IV e V."],"a":0,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - OJ (TJ MA)/TJ MA/2019 • TEC 1009449","source":"FCC - OJ (TJ MA)/TJ MA/2019","subject":"Direito Processual Civil - Do Tempo e Do Lugar dos Atos Processuais (arts. 212 a 217)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1009449","year":2019,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2155376","sourceQuestionId":"2155376","t":"cpc-m07","moduleId":"cpc-m07","q":"De acordo com o Código de Processo Civil,","o":["a parte incapaz não poderá renunciar ao prazo estabelecido exclusivamente em seu favor, salvo se demonstrado que a renúncia a favorece.","nenhuma das partes poderá renunciar ao prazo estabelecido exclusivamente em seu favor, exceto no tocante aos prazos para interposição de recurso.","qualquer das partes poderá renunciar ao prazo estabelecido exclusivamente em seu favor, inclusive no tocante aos prazos para interposição de recurso, desde que o faça de maneira expressa.","qualquer das partes poderá, tácita ou expressamente, renunciar ao prazo estabelecido exclusivamente em seu favor, exceto no tocante aos prazos para interposição de recurso.","o réu poderá renunciar ao prazo estabelecido exclusivamente em seu favor, exceto no tocante ao prazo para contestar e reconvir."],"a":2,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022 • TEC 2155376","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Dos Prazos (arts. 218 a 235)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2155376","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021914","sourceQuestionId":"2021914","t":"cpc-m07","moduleId":"cpc-m07","q":"Embora os atos processuais sejam públicos, os processos deverão tramitar em segredo de justiça quando","o":["tiverem como parte pessoa absolutamente incapaz.","nele constarem dados protegidos pelo direito constitucional à intimidade.","envolverem interesse de espólio.","versarem sobre arbitragem, ainda que não haja sido estipulada cláusula de confidencialidade.","tratarem de cobrança de créditos públicos."],"a":1,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ass Proc (PGE AM)/PGE AM/2022 • TEC 2021914","source":"FCC - Ass Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Forma dos Atos Processuais (arts. 188 a 211)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021914","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-413606","sourceQuestionId":"413606","t":"cpc-m07","moduleId":"cpc-m07","q":"Penélope recebeu pessoalmente, em sua casa, em um domingo às 22 horas, um mandado de citação para responder à demanda contra si ajuizada. Em sua defesa, Penélope alegou que a citação é nula, pois os atos processuais devem ser realizados apenas em dias úteis, das 6 às 20 horas. Esta alegação","o":["não procede, pois o ato processual denominado citação pode ser praticado, independente de autorização judicial, durante o período de férias forenses e nos feriados ou dias úteis fora do horário forense.","procede, já que os domingos são considerados feriados, para efeito forense.","parcialmente procede, eis que a citação, embora válida, é inexistente, porque realizada fora do horário forense.","procede, pois a citação não se referia à tutela de urgência, única hipótese possível para a prática de atos processuais durante férias e feriados forenses.","não procede, pois a citação é válida, eis que não existe limite para as tentativas de localização pelo Oficial de Justiça, fora do horário comercial."],"a":0,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TNS (PGM Teresina)/Pref Teresina/Analista Administrativo/2016 • TEC 413606","source":"FCC - TNS (PGM Teresina)/Pref Teresina/Analista Administrativo/2016","subject":"Direito Processual Civil - Do Tempo e Do Lugar dos Atos Processuais (arts. 212 a 217)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/413606","year":2016,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2271830","sourceQuestionId":"2271830","t":"cpc-m07","moduleId":"cpc-m07","q":"Considere as seguintes assertivas acerca dos prazos: I. É considerado intempestivo o ato praticado antes do termo inicial do prazo. II. Quando a lei ou o juiz não determinar prazo, as intimações somente obrigarão a comparecimento após decorridos cinco dias. III. O prazo processual estabelecido pelo juiz é contado em dias corridos, ao passo que, na contagem de prazo processual estabelecido por lei, computar-se-ão somente os dias úteis. IV. O juiz não pode reduzir prazos peremptórios sem anuência das partes, ainda que repute a medida conveniente à celeridade processual. V. Desde que o faça de maneira expressa, a parte poderá renunciar ao prazo estabelecido exclusivamente em seu favor, faculdade que se aplica até mesmo em relação aos prazos para a interposição de recursos. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS nos itens","o":["I e II.","I e III.","II e IV.","III e V.","IV e V."],"a":4,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/\"Sem Especialidade\"/2022 • TEC 2271830","source":"FCC - AJ TRT17/TRT 17/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Dos Prazos (arts. 218 a 235)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2271830","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021915","sourceQuestionId":"2021915","t":"cpc-m07","moduleId":"cpc-m07","q":"Os atos das partes","o":["produzem, em regra, efeitos processuais imediatos, ressalvada a desistência da ação, que depende de homologação judicial.","geram efeitos apenas se homologados pelo Juiz.","não estão sujeitos à preclusão temporal.","podem ser praticados, diretamente, por qualquer pessoa, goze ou não de capacidade civil.","não demandam assistência, salvo se a parte for absolutamente incapaz."],"a":0,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ass Proc (PGE AM)/PGE AM/2022 • TEC 2021915","source":"FCC - Ass Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Forma dos Atos Processuais (arts. 188 a 211)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021915","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-177992","sourceQuestionId":"177992","t":"cpc-m07","moduleId":"cpc-m07","q":"No tocante ao tempo e lugar dos atos processuais, considere as afirmações abaixo. I. Durante as férias e nos feriados não se praticarão aos processuais, com a única exceção das medidas cautelares urgentes. II. Entre outros, processam-se durante as férias e não se suspendem pela superveniência delas os atos de jurisdição voluntária, bem como os necessários à conservação de direitos, quando possam ser prejudicados pelo adiamento. III. Os atos processuais realizam-se necessariamente na sede do juízo, só se efetuando em outro lugar em razão de obstáculo arguido pelo interessado e acolhido pelo juiz. Está correto o que se afirma APENAS em","o":["III.","I.","II.","I e II.","II e III."],"a":2,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc Leg (CM SP)/CM SP/2014 • TEC 177992","source":"FCC - Proc Leg (CM SP)/CM SP/2014","subject":"Direito Processual Civil - Do Tempo e Do Lugar dos Atos Processuais (arts. 212 a 217)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/177992","year":2014,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-1147298","sourceQuestionId":"1147298","t":"cpc-m07","moduleId":"cpc-m07","q":"Alberto Roberto tornou-se réu em uma ação de cobrança de nota promissória. Ficou sabendo por um escrevente do Cartório, procurou um advogado e, antes mesmo de ser citado, contestou o feito. Essa contestação","o":["será tida por intempestiva, pois o que define a tempestividade é o início da contagem do prazo, ainda não iniciado.","será considerada tempestiva, sem necessidade de reiteração do ato após a citação de Alberto Roberto.","será considerada um ato praticado condicionalmente, pois dependerá de ratificação por Alberto Roberto, necessariamente dentro do prazo legal de oferecimento da defesa.","é intempestiva, porque praticado o ato fora do prazo, o que se dá tanto antes quanto depois de finalizada sua contagem; no entanto, se o autor concordar, será a contestação tida por tempestiva, caracterizando a anuência um negócio jurídico- processual.","será tida por inexistente, devendo ser praticado o ato novamente no prazo legal da contestação"],"a":1,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJMS/TJ MS/2020 • TEC 1147298","source":"FCC - JE TJMS/TJ MS/2020","subject":"Direito Processual Civil - Dos Prazos (arts. 218 a 235)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1147298","year":2020,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2032360","sourceQuestionId":"2032360","t":"cpc-m07","moduleId":"cpc-m07","q":"No que se refere aos pronunciamentos do juiz, prescreve o Código de Processo Civil: I. Sentença é o pronunciamento pelo qual o juiz põe fim ao processo, decidindo o mérito. II. Ressalvadas as disposições expressas dos procedimentos especiais, sentença é o pronunciamento por meio do qual o juiz põe fim à fase cognitiva do procedimento comum, bem como extingue a execução. III. Decisão interlocutória é todo pronunciamento judicial de natureza decisória que não se enquadre no conceito de sentença. IV. Despachos são todos os pronunciamentos do juiz praticados no processo, de ofício ou a requerimento da parte, inclusive os atos meramente ordinatórios, como juntadas ou vistas obrigatórias. Está correto o que se afirma APENAS em","o":["I e III.","II e III.","II, III e IV.","I e IV.","I, II e IV."],"a":1,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2022 • TEC 2032360","source":"FCC - Proc (UNICAMP)/UNICAMP/2022","subject":"Direito Processual Civil - Da Forma dos Atos Processuais (arts. 188 a 211)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2032360","year":2022,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-228239","sourceQuestionId":"228239","t":"cpc-m07","moduleId":"cpc-m07","q":"Considere: I. Perda da faculdade processual em função do decurso do prazo previsto em lei ou assinado pelo juiz sem o seu exercício. II. Perda da faculdade processual em razão da prática de ato incompatível com aquele que se pretende realizar. Os conceitos acima dizem respeito, respectivamente, à preclusão","o":["lógica e consumativa.","temporal e lógica.","lógica e temporal.","temporal e consumativa.","consumativa e temporal."],"a":1,"e":"Tema classificado no Módulo 7: Atos processuais, negócios, tempo, lugar e prazos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ACE (TCE-GO)/TCE GO/Jurídica/2014 • TEC 228239","source":"FCC - ACE (TCE-GO)/TCE GO/Jurídica/2014","subject":"Direito Processual Civil - Do Tempo e Do Lugar dos Atos Processuais (arts. 212 a 217)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/228239","year":2014,"classificationReason":"Atos processuais e prazos expressamente previstos.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3853428","sourceQuestionId":"3853428","t":"cpc-m08","moduleId":"cpc-m08","q":"A citação por edital será feita","o":["quando o citando residir em local não atendido pela entrega domiciliar de correspondência.","quando desconhecido ou incerto o citando.","em todas as ações de Estado.","quando o citando for incapaz.","se o autor, ainda que imotivadamente, a requerer."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026 • TEC 3853428","source":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3853428","year":2026,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488270","sourceQuestionId":"2488270","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, quando a lei prescrever determinada forma,","o":["o juiz invalidará o ato sempre que esta não for respeitada, determinando sua repetição apenas se puder decidir o mérito a favor da parte a quem aproveita a decretação da nulidade.","o juiz invalidará o ato sempre que esta não for respeitada, considerando de nenhum efeito todos os subsequentes, sejam ou não dependentes do ato nulo.","o juiz considerará válido o ato se, realizado de outro modo, lhe alcançar a finalidade.","sob pena de nulidade, a decretação desta poderá ser requerida inclusive pela parte a que lhe deu causa.","o juiz invalidará o ato sempre que esta não for respeitada, determinando, necessariamente, sua repetição."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488270","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488270","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3956203","sourceQuestionId":"3956203","t":"cpc-m08","moduleId":"cpc-m08","q":"Para responder as questões de números 50 e 51 considere a existência de ação de reintegração de posse promovida por pessoa física em face de coletividade. A Defensoria Pública, atuando na qualidade de custos vulnerabilis, apresentou contestação e, na ocasião, não tinha informações a respeito do valor do terreno objeto da lide. Após a perícia, houve a comprovação de que o valor do terreno era bastante superior ao indicado pelo autor da ação. Nesse caso,","o":["houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, não podendo ser modificado o conteúdo econômico ou ao proveito econômico perseguido pelo autor após fase processual.","houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, podendo ser modificado o conteúdo econômico apenas em sentença, ocasião em que o novo valor atribuído determinará o recolhimento das custas e despesas judiciais futuras.","o juiz corrigirá, de ofício e por arbitramento, o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão, contudo sem a possibilidade de complementação de custas iniciais, valendo-se o novo valor para determinar as custas e despesas judiciais futuras.","o juiz corrigirá, de ofício e por arbitramento, o valor da causa quando verificar que não corresponde ao conteúdo patrimonial em discussão, caso em que se procederá o recolhimento das custas correspondentes.","houve preclusão da impugnação do valor da causa por não ter sido arguida em contestação, podendo ser modificado o conteúdo econômico apenas em sentença, ocasião em que se procederá ao recolhimento das custas iniciais correspondentes e determinará o recolhimento das custas e despesas judiciais futuras."],"a":3,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956203","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956203","year":2026,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021918","sourceQuestionId":"2021918","t":"cpc-m08","moduleId":"cpc-m08","q":"As cartas","o":["têm caráter itinerante.","não precisam ser cumpridas pelo juízo destinatário se este discordar de seu conteúdo.","podem ser expedidas apenas pelos juízos de primeira instância.","deverão ser expedidas preferencialmente em meio físico e encaminhadas pelos Correios.","são chamadas precatórias quando se dirigirem a autoridade judiciária de outro país."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ass Proc (PGE AM)/PGE AM/2022 • TEC 2021918","source":"FCC - Ass Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021918","year":2022,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883935","sourceQuestionId":"3883935","t":"cpc-m08","moduleId":"cpc-m08","q":"As prerrogativas da Defensoria Pública visam equilibrar a relação processual diante das dificuldades estruturais da assistência jurídica aos necessitados. No que tange à comunicação dos atos processuais no regime do CPC e legislações correlatas,","o":["nos processos que tramitam sob o rito dos Juizados Especiais Cíveis, a legislação específica estabelece a contagem em dias corridos, mas não veda expressamente a prerrogativa do prazo em dobro em relação à Defensoria Pública.","a intimação pessoal do Defensor Público, realizada mediante carga, remessa dos autos ou acesso ao portal eletrônico próprio, é condição de validade do ato, não sendo suprida pela mera publicação em Diário de Justiça Eletrônico, ainda que conste o nome do membro da instituição.","a contagem do prazo em dobro para a Defensoria Pública inicia-se automaticamente no dia útil seguinte à disponibilização da decisão no sistema eletrônico, independentemente de acesso deliberado do defensor ao arquivo ou sistema.","no cumprimento de sentença contra a Fazenda Pública, o prazo para a Defensoria Pública apresentar impugnação é contado de forma simples, por se tratar de incidente de natureza autônoma.","o benefício do prazo em dobro aplica-se apenas às manifestações de mérito, excluindo-se atos puramente ordinatórios ou administrativos praticados no bojo do processo judicial."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883935","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883935","year":2026,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670623","sourceQuestionId":"3670623","t":"cpc-m08","moduleId":"cpc-m08","q":"NÃO representa motivo justificador da distribuição de causas por dependência a","o":["existência de conexão entre elas.","existência de continência entre elas, nos casos em que a ação continente tiver sido proposta anteriormente.","reiteração de pedido antes formulado em processo extinto sem resolução de mérito, ainda que em lIitisconsórcio com outros autores não participantes do primeiro processo.","possibilidade de prolação de decisões conflitantes acaso decididas separadamente, ainda que não haja conexão entre elas.","apresentação de oposição."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670623","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Distribuição e do Registro (arts. 284 a 290)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670623","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3296975","sourceQuestionId":"3296975","t":"cpc-m08","moduleId":"cpc-m08","q":"A citação da pessoa jurídica de direito privado será válida se entregue a","o":["pessoa com poderes de gerência geral ou de administração, não se admitindo o recebimento por funcionário responsável pelo recebimento de correspondências, via meio eletrônico, correio ou mandado de citação.","pessoa com poderes de gerência geral ou de administração ou, ainda, a funcionário responsável pelo recebimento de correspondências, via meio eletrônico, correio ou mandado de citação.","pessoa com poderes de gerência geral ou de administração ou, ainda, a funcionário responsável pelo recebimento de correspondências, via de mandado de citação exclusivamente.","qualquer funcionário que estiver no endereço da sede, via meio eletrônico, correio ou mandado de citação.","pessoa com poderes de gerência geral ou de administração, não se admitindo o recebimento por funcionário responsável pelo recebimento de correspondências, via de mandado de citação exclusivamente."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025 • TEC 3296975","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3296975","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2032364","sourceQuestionId":"2032364","t":"cpc-m08","moduleId":"cpc-m08","q":"No que se refere às nulidades processuais, o Código de Processo Civil estabelece:","o":["Quando a lei prescrever determinada forma, o juiz considerará válido o ato se, ainda que realizado de outro modo, a sua finalidade for alcançada.","Quando a lei prescrever determinada forma sob pena de nulidade, tanto o Ministério Público, como as partes, ainda que lhe tenham dado causa, poderão requerer a sua decretação, respondendo posteriormente por eventual litigância de má-fé.","Nos feitos em que o Ministério Público deva intervir, caso não haja intimação de seu membro para acompanhar o processo, o juiz invalidará todos os atos desde o início do processo, pois o prejuízo nesse caso é presumido.","Ainda que pudessem ser reconhecidas de ofício pelo juiz, precluem as nulidades quando a parte não as alega na primeira oportunidade em que lhe couber falar nos autos.","Anulado o ato, todos os atos a ele subsequentes, dele dependentes ou não, serão considerados nulos de pleno direito."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2022 • TEC 2032364","source":"FCC - Proc (UNICAMP)/UNICAMP/2022","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2032364","year":2022,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3542710","sourceQuestionId":"3542710","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a impugnação ao valor da causa atribuido pelo autor deverá ser formulada","o":["em preliminar da contestação, sob pena de preclusão para a parte.","em preliminar da contestação, mas não se sujeita a preclusão, podendo ser suscitada a qualquer tempo, inclusive em apelação ou contrarrazões de apelação, desde que antes do trânsito em julgado.","em preliminar da contestação, mas não se sujeita a preclusão, podendo ser suscitada a qualquer tempo, desde que anteriormente à prolação de sentença ou à decisão saneadora, se não ocorrer o julgamento antecipado.","no prazo de contestação, mas em petição a ela apartada sob pena de preclusão.","até o saneamento do processo, por meio de petição específica, que será processada em autos próprios."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025 • TEC 3542710","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3542710","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1818197","sourceQuestionId":"1818197","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a carta rogatória será expedida para que órgão jurisdicional","o":["estrangeiro pratique ato de cooperação jurídica internacional, relativo a processo em curso perante órgão jurisdicional brasileiro.","brasileiro pratique ou determine o cumprimento, na área de sua competência territorial, de ato relativo a pedido de cooperação judiciária formulado por órgão jurisdicional de competência territorial diversa.","estrangeiro ou brasileiro pratique ou determine o cumprimento, na área de sua competência territorial, de ato objeto de pedido de cooperação judiciária formulado por juízo arbitral, inclusive os que importem efetivação de tutela provisória.","da primeira instância pratique, na área de sua competência territorial, ato objeto de determinação de Tribunal.","integrante de outro ramo da Justiça brasileira pratique ou determine o cumprimento de ato relativo a pedido de cooperação judiciária."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ Aux (TJ SC)/TJ SC/2021 • TEC 1818197","source":"FCC - TJ Aux (TJ SC)/TJ SC/2021","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1818197","year":2021,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3472569","sourceQuestionId":"3472569","t":"cpc-m08","moduleId":"cpc-m08","q":"Marcelo foi réu em uma ação de indenização que tramitou perante uma das varas cíveis de Manaus. Ele foi pessoalmente citado, mas não constituiu procurador e tampouco apresentou contestação. Houve sentença de procedência do pedido e, um mês apôs o trânsito em julgado, a parte autora iniciou o cumprimento de sentença para o recebimento dos valores. Houve a expedição de carta com aviso de recebimento para a Intimação de Marcelo no mesmo endereço do processo de conhecimento, mas esta retornou negativa com a informação de que ele havia se mudado. Nesse caso. de acordo com o Código de Processo Civil,","o":["a parte autora deverá promover diligências para localizar o paradeiro de Marcelo, pois o cumprimento de sentença só poderá ser realizado após a intimação pessoal frutífera do devedor.","será necessária a intimação pessoal do devedor para o cumprimento do título judicial e, na hipótese de não localização do devedor, a Defensoria Pública deverá atuar nos autos como curador especial de Marcelo.","reputa-se válida a intimação dirigida ao endereço do réu constante do processo de conhecimento, ainda que não assinada por Marcelo, pois a obrigação de comunicar previamente o juízo acerca da mudança de residência é do devedor.","será necessária a intimação de Marcelo por edital, e se ele não se manifestar nos autos no prazo legal, a Defensoria Pública deverá atuar como curador especial do executado.","deverá ser reconhecida a nulidade total da demanda, tendo em vista que, no processo de conhecimento, não houve nomeação de curador especial ao réu revel, nem a apresentação de contestação."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2025 • TEC 3472569","source":"FCC - DP AM/DPE AM/2025","subject":"Direito Processual Civil - Das Intimações (arts. 269 a 275)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3472569","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3375491","sourceQuestionId":"3375491","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, é correto afirmar:","o":["Nos casos em que houver litisconsórcio necessário, ter-se-á cumulação de ações, sendo obrigatório, para tanto, que o juízo detenha competência em razão da matéria para o julgamento de todas as ações cumuladas.","Para que seja considerada lícita a cumulação, em um único processo, contra o mesmo réu, de vários pedidos, é obrigatório que entre eles haja conexão.","A citação válida, ainda quando ordenada por juízo incompetente, induz litispendência, torna litigiosa a coisa, bem como previne o juízo.","A interrupção da prescrição, operada pelo despacho que ordena a citação, ainda que proferido por juízo incompetente, retroagirá à data de propositura da ação.","Havendo sido cumulados pedidos sujeitos a tipos diversos de procedimento, é vedado ao autor indicar o procedimento comum como aplicavel ao caso."],"a":3,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375491","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Da Citação (arts. 238 a 259)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375491","year":2025,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2239318","sourceQuestionId":"2239318","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com as normas do Código de Processo Civil em matéria de nulidade,","o":["quando a lei prescrever determinada forma sob pena de nulidade, a decretação desta pode ser requerida por qualquer das partes, inclusive por aquela que lhe deu causa, caso em que ficará responsável pelas custas da repetição do ato.","a inobservância da forma prescrita em lei para a prática do ato acarreta a sua nulidade absoluta, não sendo dado ao juiz considerá-lo válido mesmo quando, realizado de outro modo, tenha alcançado sua finalidade.","a nulidade dos atos deve ser alegada na primeira oportunidade em que couber à parte falar nos autos, sob pena de preclusão; entretanto, essa preclusão não se aplica às nulidades que o juiz deva decretar de ofício.","ainda que possa decidir o mérito a favor da parte a quem aproveite a decretação da nulidade, o juiz não poderá deixar de pronunciá-la e de determinar a repetição, o ato ou o suprimento da sua falta.","se um ato for anulado pela mera inobservância da forma prescrita em lei, preservam-se a validade e a eficácia de todos os atos subsequentes, mesmo que dele dependam."],"a":2,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2239318","source":"FCC - AJ TRT14/TRT 14/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Das Nulidades (arts. 276 a 283)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2239318","year":2022,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126466","sourceQuestionId":"3126466","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, o valor da causa será","o":["corrigido de ofício e por arbitramento quando o juiz verificar que não corresponde ao conteúdo patrimonial em discussão ou ao proveito econômico perseguindo pelo autor.","impugnado pelo réu em incidente autônomo, distribuído por dependência ao processos principal.","o valor do pedido principal, na ação em que houver pedidos alternativos.","a quantia correspondente à somatória do pedido principal com o subsídio nas ações em que este foi formulado.","dispensado, se a causa não tiver conteúdo econômico imediatamente aferível."],"a":0,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126466","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Do Valor da Causa (Arts. 291 a 293)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126466","year":2024,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1071912","sourceQuestionId":"1071912","t":"cpc-m08","moduleId":"cpc-m08","q":"De acordo com o Código de Processo Civil, a carta precatória","o":["deverá ser instruída com as cópias necessárias à realização do ato deprecado, vedada, em qualquer hipótese, a remessa de documento original.","tem caráter itinerante, podendo, mesmo antes de lhe ser ordenado o cumprimento, ser encaminhada a juízo diverso do que dela consta, a fim de se praticar o ato.","será expedida, preferencialmente, por meio físico, salvo quando enviada a órgão jurisdicional integrante do mesmo tribunal, caso em que adotará preferencialmente o meio eletrônico.","não poderá, em nenhuma hipótese, ter seu cumprimento recusado pelo juízo deprecado, sob pena de, assim o fazendo, incorrer em responsabilidade funcional.","deverá ser transmitida por correio, malote, pela internet ou por qualquer outro meio idôneo que garanta a aferição da sua autenticidade, sendo vedada a transmissão por telefone."],"a":1,"e":"Tema classificado no Módulo 8: Comunicação, nulidades, distribuição e valor da causa. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019 • TEC 1071912","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Das Cartas (arts. 260 a 268)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071912","year":2019,"classificationReason":"Comunicação, nulidade, distribuição ou valor da causa.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937727","sourceQuestionId":"3937727","t":"cpc-m09","moduleId":"cpc-m09","q":"Maria, idosa e aposentada, foi diagnóstica com doença grave que necessitava de tratamento específico de saúde. O plano de saúde negou o fornecimento do tratamento indicado pelo médico. Em ação de obrigação de fazer promovida pela Defensoria Pública contra a operadora do plano de saúde, o Juiz condicionou a concessão da tutela de urgência à prestação de caução real. A caução","o":["poderá ser dispensada somente se a demanda não tiver conteúdo econômico em seu objeto.","poderá ser dispensada se a parte economicamente hipossuficiente não puder oferecê-la.","deverá ser exigida independentemente da capacidade econômica da parte em prestá-la.","deverá ser exigida no valor um salário mínimo independentemente da capacidade econômica da parte em prestá-la.","deverá ser exigida no valor um salário mínimo se a parte for economicamente hipossuficiente."],"a":1,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937727","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937727","year":2026,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937776","sourceQuestionId":"3937776","t":"cpc-m09","moduleId":"cpc-m09","q":"Comunidade periférica, em demanda coletiva, alega omissão estatal continuada em providências básicas de infraestrutura (água potável e saneamento), com impactos permanentes à saúde e à dignidade dos moradores. O ente público demandado suscita que a pretensão é “inexigível” pela incidência da prescrição quinquenal. Segundo as regras de prescrição aplicável ao caso,","o":["a pretensão de cessação do ilícito e conformação prospectiva não se extingue por prescrição, em omissão continuada que renova a lesão a direitos fundamentais, podendo haver limitação temporal quanto ao alcance de eventual direito indenizatório.","verifica-se a ocorrência da prescrição quinquenal integral a partir do primeiro ato omissivo, ainda que a lesão se renove diariamente, pois o Estado não pode ficar sujeito a demandas indefinidas por fatos antigos.","toda pretensão coletiva é imprescritível, por envolver direitos difusos e interesse público, sendo inaplicável qualquer regime prescricional em face do Poder Público.","o decurso do prazo prescricional se inicia no momento em que a Defensoria Pública ou o Ministério Público tenham ciência formal da omissão, pois antes disso não há possibilidade de exercício da pretensão.","aplica-se sempre o prazo decenal do Código Civil quando se tratar de políticas públicas, pois é obrigação de fazer não especificada em lei especial."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937776","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Tutela Provisória","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937776","year":2026,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3986950","sourceQuestionId":"3986950","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de evidência","o":["depende da demonstração de perigo de dano ou de risco ao resultado útil do processo.","poderá ser concedida liminarmente sempre que o tema for objeto de súmula vinculante, independentemente de prova documental pré constituída.","conserva sua eficácia na pendência do processo e só poderá ser revogada ou modificada com a sentença.","poderá ser concedida se ficar caracterizado o abuso do direito de defesa ou o manifesto propósito protelatório da parte.","poderá ser concedida liminarmente se a petição inicial for instruída com prova documental suficiente dos fatos constitutivos do direito do autor."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026 • TEC 3986950","source":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3986950","year":2026,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-394332","sourceQuestionId":"394332","t":"cpc-m09","moduleId":"cpc-m09","q":"A disposição de lei que veda concessão de medidas liminares que esgotem, no todo ou em parte, o objeto da ação proposta contra o Estado, acha mitigação jurisprudencial","o":["somente nos casos em que a impugnação, do mesmo ato de autoridade, nas vias do mandado de segurança, seja de competência originária de tribunal.","apenas em ação civil pública.","apenas em ações de interesses de pessoas idosas, por lhes ser garantida prioridade no trâmite processual.","em se tratando de aquisição de medicamento indispensável à sobrevivência da parte.","em qualquer circunstância, porque declarada inconstitucional pelo Supremo Tribunal Federal."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MA)/PGE MA/2016 • TEC 394332","source":"FCC - Proc (PGE MA)/PGE MA/2016","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Tutela Provisória","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/394332","year":2016,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3296978","sourceQuestionId":"3296978","t":"cpc-m09","moduleId":"cpc-m09","q":"Lucas ajuizou ação contra empresa para pleitear a restituição de um valor já reconhecido como devido em sede de recurso repetitivo. Considerando que Lucas possui todos os documentos para comprovar as suas alegações, o pedido que deve ser formulado por Lucas na petição inicial é de tutela provisória","o":["de evidência, que poderá ser deferida liminarmente pelo juiz.","de urgência, após o contraditório a que o réu não oponha prova capaz de gerar dúvida razoável.","de evidência, após o contraditório a que o réu não oponha prova capaz de gerar dúvida razoável.","de urgência, que poderá ser deferida liminarmente pelo juiz.","cautelar antecedente, que poderá ser deferida liminarmente pelo juiz."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025 • TEC 3296978","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3296978","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3355416","sourceQuestionId":"3355416","t":"cpc-m09","moduleId":"cpc-m09","q":"Em ação de divórcio com discussão de guarda, alimentos e partilha de bens, a autora vem enfrentando dificuldades na citação do requerido. Já foram expedidos alguns ofícios de praxe para obtenção de endereços, porém ainda não esgotadas as tentativas de localização pessoal do réu. Diante da demora na localização do requerido, a autora narrou o desejo de conseguir o divórcio independentemente da citação deste. Assim, com o objetivo de dissolver o vínculo matrimonial, no curso da ação de divórcio, a Defensoria Pública poderá requerer","o":["apenas a dispensa da realização da audiência de conciliação obrigatória.","a nomeação antecipada de curador especial ao réu.","a produção antecipada de provas.","a concessão da tutela provisória de evidência.","o julgamento antecipado da lide."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AnaDP (DPE SP)/DPE SP/2025 • TEC 3355416","source":"FCC - AnaDP (DPE SP)/DPE SP/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3355416","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3451259","sourceQuestionId":"3451259","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere o Código de Processo Civil brasileiro para responder à questão. A tutela provisória de urgência","o":["só poderá ser modificada ou revogada por sentença, ao final do processo.","deve ser concedida somente após justificação prévia.","não poderá ser requerida incidentalmente no processo.","não será concedida quando houver perigo de irreversibilidade dos efeitos da decisão.","implicará no pagamento de custas, se requerida em caráter incidental."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451259","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451259","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3453281","sourceQuestionId":"3453281","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória de urgência será concedida","o":["quando houver elementos que evidenciem a probabilidade do direito, podendo o Juiz, conforme o caso, exigir caução real ou fidejussória idônea.","independentemente da demonstração de perigo de dano, se ficar demonstrada a violação a enunciado de súmula do Supremo Tribunal Federal.","independentemente da demonstração de perigo de dano, se ficar caracterizado o manifesto propósito protelatório da parte.","quando houver elementos que evidenciem risco ao resultado útil do processo, sendo vedado ao Juiz exigir caução real ou fidejussória idônea.","de forma antecipada mesmo quando houver perigo de irreversibilidade dos efeitos da decisão."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025 • TEC 3453281","source":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3453281","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670668","sourceQuestionId":"3670668","t":"cpc-m09","moduleId":"cpc-m09","q":"Considere as assertivas abaixo acerca da tutela provisória de urgência: I. Uma vez concedida e, posteriormente, sendo suspenso o processo, também sua eficácia será suspensa, salvo decisão judicial em sentido contrário. II. Se requerida na forma incidental, independe do pagamento de custas, sendo competente o mesmo juízo que conhecerá do pedido de tutela definitiva. III. O Código de Processo Civil em vigor eliminou a figura das medidas cautelares nominadas, com requisitos próprios, tal como previsto na lei processual anterior. IV. Em sua modalidade antecipada, visa combater o que se denomina “perigo de infrutuosidade” da tutela jurisdicional. Está correto o que se afirma APENAS em","o":["II e III.","III e IV.","I e II.","II e IV.","I e III."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670668","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670668","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3679840","sourceQuestionId":"3679840","t":"cpc-m09","moduleId":"cpc-m09","q":"Quanto à tutela de urgência antecipada antecedente:","o":["Não exige a demonstração de risco de dano, mas apenas da aparência do direito almejado.","Uma vez estabilizada, poderá ser invalidada por decisão proferida em ação rescisória, a ser proposta no prazo de até 2 anos.","Exige que, na petição inicial, seja indicado o valor da causa, estabelecido com base no conteúdo econômico da providência pretendida a titulo de antecipação.","Se indeferida pelo juízo, caberá ao autor a emenda da petição Inicial no prazo de 15 dias, sob pena de extinção do processo sem exame de mérito.","Não se estabilizará se o réu interpuser recurso contra a decisão que a concedeu, sendo desinfluente a vontade do autor, expressa na petição inicial, em valer-se de tal sistemática."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679840","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679840","year":2025,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3021777","sourceQuestionId":"3021777","t":"cpc-m09","moduleId":"cpc-m09","q":"De acordo com o Código de Processo Civil, a tutela de evidência","o":["não pode ser deferida liminarmente.","não pode ter por objeto a obrigação de fazer.","pode ser concedida sem prévia oitiva da parte contra quem ela se dirige.","não pode ser concedida em ação que versar sobre direito indisponível.","só pode ser concedida se houver perigo de dano grave e irreparável."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024 • TEC 3021777","source":"FCC - AJ TRF3/TRF 3/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3021777","year":2024,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1981238","sourceQuestionId":"1981238","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de evidência será concedida quando","o":["houver, independentemente da matéria de fato, houver enunciado de súmula do Supremo Tribunal Federal ou do Superior Tribunal de Justiça.","ficar caracterizado o manifesto propósito protelatório da parte e houver a demonstração de perigo de dano ou de risco ao resultado útil do processo.","a petição inicial for instruída com prova documental suficiente dos fatos constitutivos do direito do autor, independentemente do conteúdo da manifestação do réu.","as alegações de fato puderem ser comprovadas apenas documentalmente e houver tese firmada em julgamento de casos repetitivos.","as alegações de fato puderem ser comprovadas apenas documentalmente e houver a demonstração de perigo de dano ou de risco ao resultado útil do processo."],"a":3,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP PB/DPE PB/2022 • TEC 1981238","source":"FCC - DP PB/DPE PB/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1981238","year":2022,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021309","sourceQuestionId":"2021309","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela provisória","o":["pode ser requerida em caráter incidental, e, nesta hipótese, não necessita do pagamento de custas.","será concedida apenas se demonstrado perigo de dano irreversível à parte ou ao processo.","não pode ser modificada pelo juiz que a concedeu.","não está sujeita a recurso.","deve ser pleiteada sempre ao juízo de primeira instância."],"a":0,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Proc (PGE AM)/PGE AM/2022 • TEC 2021309","source":"FCC - Ana Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021309","year":2022,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2073338","sourceQuestionId":"2073338","t":"cpc-m09","moduleId":"cpc-m09","q":"A tutela de urgência:","o":["Conserva sua eficácia na pendência do processo, só podendo ser revogada ou modificada por ocasião da prolação da sentença.","Depende da inequivocidade do direito, ou seja, sua certeza, para ser concedida.","Por sua própria natureza, só pode ser concedida liminarmente.","Uma vez concedida, o recurso adequado é a apelação, já que antecipou o provimento jurisdicional final.","Se de natureza cautelar, pode ser efetivada mediante arresto, sequestro, arrolamento de bens, registro de protesto contra alienação de bem e qualquer outra medida idônea para asseguração do direito."],"a":4,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (Teresina)/Pref Teresina/2022 • TEC 2073338","source":"FCC - Proc (Teresina)/Pref Teresina/2022","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2073338","year":2022,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1736850","sourceQuestionId":"1736850","t":"cpc-m09","moduleId":"cpc-m09","q":"O valor da causa","o":["constitui matéria dispositiva, não podendo ser alterado, a pedido da parte nem de ofício, se não constar de impugnação, em preliminar de contestação.","corresponde à somatória dos pedidos principal e subsidiário, nas ações que contenham pedidos principal e subsidiário.","deve levar em consideração o pedido de tutela final, no procedimento de tutela antecipada requerida em caráter antecedente.","é utilizado, qualquer que seja, como base de cálculo para fixação dos honorários advocatícios, nas causas em que impossível mensurar o proveito econômico.","pode ser meramente estimado, e não o da condenação pretendida, nas ações nas quais se pede compensação por dano moral."],"a":2,"e":"Tema classificado no Módulo 9: Tutela provisória de urgência e de evidência. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJGO/TJ GO/2021 • TEC 1736850","source":"FCC - JE TJGO/TJ GO/2021","subject":"Direito Processual Civil - Da Tutela Provisória (arts. 294 a 311)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1736850","year":2021,"classificationReason":"Tutela provisória expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3821948","sourceQuestionId":"3821948","t":"cpc-m10","moduleId":"cpc-m10","q":"No que concerne à petição inicial, em conformidade com o Código de Processo Civil,","o":["indeferida a petição inicial, o autor poderá apelar, facultado ao juiz, no prazo de 15 dias, retratar-se e, se não houver retratação, o juiz mandará citar o réu para responder ao recurso.","considera-se inepta a petição inicial, dentre outras situações, sempre que o pedido for indeterminado.","é lícita a cumulação, em um único processo, contra o mesmo réu, de vários pedidos, somente se entre eles houver conexão.","o autor poderá, até o saneamento do processo, aditar ou alterar o pedido e a causa de pedir, independentemente de consentimento do réu, assegurado o contraditório mediante a possibilidade de manifestação deste no prazo mínimo de 15 dias, facultado o requerimento de prova suplementar.","o pedido deve ser determinado, porém, é lícito formular pedido genérico, quando, dentre outras situações, a determinação do objeto ou do valor da condenação depender de ato que deva ser praticado pelo réu."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821948","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821948","year":2026,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488266","sourceQuestionId":"2488266","t":"cpc-m10","moduleId":"cpc-m10","q":"Acerca da formação, suspensão e extinção do processo, considere: I. Considera-se proposta a ação com a citação. II. Antes de extinguir o processo sem resolução de mérito, o juiz deve conceder à parte oportunidade para, se possível, corrigir o vício. III. Durante a suspensão é vedado praticar qualquer ato processual, podendo o juiz, todavia, determinar a realização de atos urgentes a fim de evitar dano irreparável, salvo no caso de arguição de impedimento e de suspeição. IV. Suspende-se o processo sempre que o requerer o credor. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["I e II.","III e IV.","I e IV.","II e III.","I e III."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488266","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488266","year":2025,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-331053","sourceQuestionId":"331053","t":"cpc-m10","moduleId":"cpc-m10","q":"Ao despachar petição inicial, o juiz verificou existir vício sanável e determinou a emenda no prazo de 10 dias. No entanto, na fluência do prazo, o autor requereu sua ampliação, o que foi deferido. Citado e intimado, o réu interpôs agravo de instrumento alegando ocorrência de preclusão, que, de acordo com jurisprudência dominante do Superior Tribunal de Justiça,","o":["ocorreu, pois o prazo para emenda é dilatório e não admite ampliação.","não ocorreu, pois o prazo para emenda é dilatório e admite ampliação.","ocorreu, pois o prazo para emenda é peremptório e não admite ampliação.","não ocorreu, pois o prazo para emenda é peremptório e admite dilação.","não ocorreu, pois, apesar de peremptório, o autor requereu a ampliação do prazo enquanto ainda estava fluindo."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJSE/TJ SE/2015 • TEC 331053","source":"FCC - JE TJSE/TJ SE/2015","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Formação, Suspensão e Extinção do Processo","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/331053","year":2015,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3451256","sourceQuestionId":"3451256","t":"cpc-m10","moduleId":"cpc-m10","q":"Considere o Código de Processo Civil brasileiro para responder à questão. A apelação interposta contra o indeferimento da inicial gerará a citação do réu para","o":["apresentar contestação e responder o recurso, concomitantemente.","apresentar contestação.","apenas tomar ciência do processo sem possibilidade de manifestação.","manifestar-se acerca de eventual juízo de retratação, apenas.","responder o recurso."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451256","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451256","year":2025,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3380063","sourceQuestionId":"3380063","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, o seguinte evento não enseja a suspensão do processo:","o":["admissão de incidente de resolução de demandas repetitivas.","convenção das partes.","arguição de suspeição do juiz.","morte de um dos autores, no caso de haver litisconsórcio ativo facultativo.","pedido de gratuidade da justiça formulado após a primeira manifestação da parte na instância."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025 • TEC 3380063","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3380063","year":2025,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-331076","sourceQuestionId":"331076","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com jurisprudência dominante do Superior Tribunal de Justiça, a propositura de ação cautelar de exibição de documentos bancários","o":["é cabível como medida preparatória, a fim de instruir a ação principal, demandando a demonstração da existência de relação jurídica e a ausência de entrega do documento à parte quando da contratação, independentemente de prova de pedido prévio à instituição financeira e do pagamento do custo do serviço, ainda que exista previsão contratual ou normatização da autoridade monetária.","não é cabível, visto tratar-se de documento franqueado à parte quando da celebração do contrato.","somente é cabível se não se tratar de documento padronizado e disponibilizado, de maneira clara, ao público em geral.","é cabível como medida preparatória, a fim de instruir a ação principal, bastando a demonstração da existência de relação jurídica entre as partes, a comprovação de prévio pedido à instituição financeira, não atendido em prazo razoável, e o pagamento do custo do serviço conforme previsão contratual e normatização da autoridade monetária.","é cabível como medida preparatória, a fim de instruir a ação principal, independentemente do cumprimento de requisitos específicos, senão os previstos para as cautelares em geral."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJSE/TJ SE/2015 • TEC 331076","source":"FCC - JE TJSE/TJ SE/2015","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Formação, Suspensão e Extinção do Processo","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/331076","year":2015,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3571728","sourceQuestionId":"3571728","t":"cpc-m10","moduleId":"cpc-m10","q":"Ao verificar que a petição inicial não preenchia os requisitos legais, o juiz proferiu decisão determinando ao autor que promovesse a sua emenda no prazo de 05 dias, sob pena de indeferimento. Dessa decisão, o autor foi intimado somente pela imprensa, na pessoa do seu advogado, mas não promoveu a emenda no prazo determinado pelo juiz. Em razão disso, o juiz indeferiu a petição inicial e extinguiu o processo, mesmo sem determinar a intimação pessoal do autor para correção do vício da petição inicial. Nesse caso, de acordo com o Código de Processo Civil, o juiz agiu","o":["corretamente, porque, não sendo corrigido o vício da petição inicial no prazo de 05 dias, impunha-se o seu indeferimento, independentemente de intimação pessoal do autor para promover a emenda.","incorretamente, porque o prazo para emenda da petição inicial não poderá ser fixado em menos de 10 dias; além disso, decorrido o prazo sem a correção dos vícios da petição inicial, caberia ao juiz ter concedido ao autor uma nova oportunidade de promover a emenda antes de extinguir o processo.","incorretamente, porque a petição inicial não poderia ter sido indeferida sem que antes o autor tivesse sido pessoalmente intimado a promover a emenda, sendo insuficiente para tanto a mera intimação na pessoa do seu advogado; no entanto, o prazo estipulado pelo juiz para realização a emenda está correto, já que a lei determina que ele poderá ser fixado entre 05 e 15 dias.","incorretamente, porque o prazo legal para que o autor apresente emenda à petição inicial é de 15 dias; além disso, a petição inicial não poderia ter sido indeferida sem que antes o autor fosse pessoalmente intimado a promover a emenda, sendo insuficiente para tanto a mera intimação na pessoa do seu advogado.","incorretamente, porque o prazo legal para que o autor apresente emenda à petição inicial é de 15 dias, embora seja desnecessária a sua intimação pessoal para o ato, bastando que ela seja feita na pessoa do seu advogado."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025 • TEC 3571728","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3571728","year":2025,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2155375","sourceQuestionId":"2155375","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, se o conhecimento do mérito depender de verificação da existência de fato delituoso objeto de ação penal em curso perante a justiça criminal, o juiz","o":["deve extinguir o processo, sem resolução do mérito, por falta de interesse de agir, resguardada a eficácia de medidas de caráter urgente ou satisfativas.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar por prazo indeterminado.","pode determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de um ano, ao final do qual incumbirá ao juiz cível examinar incidentalmente a questão prévia.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de três meses, ao final do qual incumbirá ao juiz cível solicitar ao juiz criminal urgência no exame da questão prévia.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo essa suspensão vigorar pelo prazo máximo de um ano, podendo ser prorrogado, uma única vez, por igual período."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022 • TEC 2155375","source":"FCC - AJ TRT9/TRT 9/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2155375","year":2022,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2874538","sourceQuestionId":"2874538","t":"cpc-m10","moduleId":"cpc-m10","q":"Suzane ajuizou demanda indenizatória, porém teve sua petição inicial indeferida, em razão de inépcia desta. Nessa situação, se Suzane interpuser apelação,","o":["o recurso deverá ser indeferido, já que o CPC prevê expressamente o cabimento de agravo de instrumento para essa hipótese.","o réu deve ser intimado para tomar ciência do processo, sem, contudo, poder apresentar contrarrazões ao recurso.","os autos serão remetidos ao tribunal sem a citação da parte requerida.","o juiz poderá retratar-se no prazo de cinco dias.","no caso de reforma da sentença pelo tribunal, o prazo para contestação será iniciado a partir da publicação do acórdão no diário oficial."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2024 • TEC 2874538","source":"FCC - AJ TRT11/TRT 11/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2874538","year":2024,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2272129","sourceQuestionId":"2272129","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, o processo não será suspenso em razão de","o":["convenção das partes.","concessão de adoção a qualquer das partes, salvo se a parte que tiver adotado for advogada atuante em causa própria e constituir a única patrona da causa.","o advogado responsável pelo processo constituir o único patrono da causa e tornar-se pai.","arguição de impedimento ou de suspeição do juiz, mas, caso venha a ser acolhida, implicará a nulidade dos atos por ele praticados.","admissão de incidente de resolução de demandas repetitivas."],"a":1,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022 • TEC 2272129","source":"FCC - AJ TRT17/TRT 17/Judiciária/Oficial de Justiça Avaliador Federal/2022","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2272129","year":2022,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3023458","sourceQuestionId":"3023458","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, se a petição inicial apresentar defeitos e irregularidades capazes de dificultar o julgamento de mérito, o juiz","o":["determinará que o autor a emende ou a complete, no prazo de 15 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo com resolução de mérito.","determinará que o autor a emende ou a complete, no prazo de 5 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo com resolução de mérito.","a Indeferirá de plano, extinguindo o processo com resolução de mérito.","determinará que o autor a emende ou a complete, no prazo de 15 dias, indicando com precisão o que deve ser corrigido ou completado, sob pena de indeferimento da petição inicial, com extinção do processo sem resolução de mérito.","a indeferirá de plano, extinguindo o processo sem resolução de mérito."],"a":3,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024 • TEC 3023458","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3023458","year":2024,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-943340","sourceQuestionId":"943340","t":"cpc-m10","moduleId":"cpc-m10","q":"Na fase de saneamento do processo, o juiz verificou que o conhecimento do mérito da demanda dependia da verificação de fato delituoso objeto de inquérito policial, não tendo ainda o Ministério Público ajuizado a correspondente ação penal. Nesse caso, o juiz","o":["pode determinar a suspensão do processo até que se pronuncie a justiça criminal; porém, se a ação penal não for proposta no prazo de 3 (três) meses, contado da intimação do ato de suspensão, deverá dar andamento ao feito e examinar incidentemente a questão prévia.","não pode determinar a suspensão do processo, cabendo-lhe examinar incidentemente a questão prévia, haja vista que as instâncias cível e criminal não se confundem.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, podendo manter o processo suspenso por prazo indeterminado, desde que a ação penal seja proposta no prazo de 3 (três) meses, contado da intimação do ato de suspensão.","somente pode ordenar a suspensão do processo, pelo prazo máximo de 1 (um) ano, a partir de quando venha a ser proposta a ação penal.","deve determinar a suspensão do processo até que se pronuncie a justiça criminal, pelo prazo mínimo de 1 (um) ano e máximo de 2 (dois), salvo se o procedimento de investigação criminal vier a ser arquivado, sem o oferecimento de denúncia"],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019 • TEC 943340","source":"FCC - AJ TRF4/TRF 4/Judiciária/Oficial de Justiça Avaliador Federal/2019","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/943340","year":2019,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126620","sourceQuestionId":"3126620","t":"cpc-m10","moduleId":"cpc-m10","q":"De acordo com o Código de Processo Civil, em ação que tenha por objeto o cumprimento de obrigação em prestações sucessivas.","o":["o autor deve requerer expressamente a condenação do réu ao pagamento das prestações vincendas, ao contrário do que se a com os juros legais, com a correção monetária e com as verbas de sucumbência, os quais estão compreendidos no principal.","o autor deve requerer expressamente a condenação do réu ao pagamento das prestações vincendas, dos juros legai, da correção monetária e das verbais de sucumbência, sob pena de preclusão.","as prestações vincendas estão incluídas no pedido, independentemente de declaração expressa do autor, assim como no principal se compreendem os juros legais, a correção monetária e as verbas de sucumbência.","as prestações não vencidas quando do ajuizamento da ação devem ser objeto de ação autônoma, tendo em vista não se admitir pedido incerto.","as prestações vincendas estão incluídas no pedido, independentemente de declaração expressa do autor, ao contrário do que se dá com os juros legais, com a correção monetária e com as verbas de sucumbência, os quais devem ser objeto de pedido expresso, sob pena de preclusão."],"a":2,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126620","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126620","year":2024,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-653959","sourceQuestionId":"653959","t":"cpc-m10","moduleId":"cpc-m10","q":"Tulio ajuizou ação monitória contra Edilson, que tramita regularmente em uma das varas cíveis do Foro Central da Comarca de São Paulo, Capital. Tulio e Edilson são representados em juízo, respectivamente e exclusivamente, pelos advogados Rodolfo e Julia. No curso do processo, durante o mês de Fevereiro deste ano de 2018, Rodolfo, advogado de Tulio, tornou-se pai após o parto de sua esposa. E no mês de abril deste mesmo ano Julia tornou-se mãe. Rodolfo e Julia comunicaram os seus clientes e apresentaram em juízo as respectivas certidões de nascimento. No caso hipotético apresentado, de acordo com o que estabelece o Código de Processo Civil, agiu corretamente o Magistrado que","o":["suspendeu o processo pelo prazo de 8 dias a partir da data do parto da esposa do advogado Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto da advogada Julia.","não suspendeu o processo após o parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 60 dias a partir da data do parto da advogada Julia.","suspendeu o processo pelo prazo de 5 dias a partir da data do parto da esposa do advogado Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto de Julia.","suspendeu o processo pelo prazo de 5 dias a partir da data do parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 60 dias a partir da data do parto de Julia.","suspendeu o processo pelo prazo de 20 dias a partir da data do parto da esposa de Rodolfo, e suspendeu o processo pelo prazo de 30 dias a partir da data do parto de Julia."],"a":0,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018 • TEC 653959","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2018","subject":"Direito Processual Civil - Da Formação, da Suspensão e da Extinção do Processo (arts. 312 a 317)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/653959","year":2018,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2740952","sourceQuestionId":"2740952","t":"cpc-m10","moduleId":"cpc-m10","q":"Considerando que a petição inicial continha o pedido condenatório ao pagamento do valor de R$ 20.000,00, sem fazer qualquer pedido expresso quanto à incidência de juros, correção monetária, verbas sucumbenciais e honorários advocatícios, de acordo com as disposições do CPC/2015 e o valor do pedido realizado pelo autor na petição inicial, a sentença:","o":["não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento citra petita.","não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento ultra petita.","pode condenar o réu ao pagamento de valor nominal superior ao pedido, pois a incidência de juros, legais e contratuais, correção monetária e verbas sucumbenciais, com exceção de honorários advocatícios, prescinde da realização de pedido expresso.","não poderá ultrapassar o valor nominal constante do pedido do autor na petição inicial, em observância ao princípio da correlação e da adstrição, sob pena de nulidade da sentença, por se tratar de julgamento extra petita.","pode condenar o réu ao pagamento de valor nominal superior ao pedido, pois a incidência de juros legais, correção monetária e verbas sucumbenciais, inclusive honorários advocatícios, prescinde da realização de pedido expresso."],"a":4,"e":"Tema classificado no Módulo 10: Formação, suspensão, extinção e petição inicial. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP ES/DPE ES/2023 • TEC 2740952","source":"FCC - DP ES/DPE ES/2023","subject":"Direito Processual Civil - Da Petição Inicial (arts. 319 a 331)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2740952","year":2023,"classificationReason":"Formação, suspensão ou petição inicial expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3853435","sourceQuestionId":"3853435","t":"cpc-m11","moduleId":"cpc-m11","q":"Na contestação, incumbe ao réu alegar matérias preliminares antes de discutir o mérito. Considere: I. prescrição. II. coisa julgada. III. incompetência relativa. IV. decadência. São matérias preliminares, o que consta APENAS de","o":["I, II e IV.","II e IV.","I, III e IV.","II e III.","I e III."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026 • TEC 3853435","source":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3853435","year":2026,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3375455","sourceQuestionId":"3375455","t":"cpc-m11","moduleId":"cpc-m11","q":"Sobre a contestação e a reconvenção no Código de Processo Civil:","o":["Para que o réu possa propor reconvenção, é obrigatório que ele tenha também apresentado contestação veiculando defesa em relação à ação principal.","Nos casos em que a ação principal houver sido proposta por substituto processual, a reconvenção deverá ser proposta contra o substituído.","O ônus da impugnação especificada dos fatos aplica-se ao defensor público apenas nos casos em que ele atuar como curador especial.","A extinção do processo sem resolução do mérito em relação à ação principal por força do não atendimento a um pressuposto processual impõe a extinção do processo em relação à reconvenção por perda de interesse de agir.","É lícito ao réu, mesmo depois de transcorrido o prazo legal para a apresentação de contestação, apresentar petição alegando prescricao do direito do autor."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375455","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375455","year":2025,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3228695","sourceQuestionId":"3228695","t":"cpc-m11","moduleId":"cpc-m11","q":"O artigo 344 do Código de Processo Civil dispõe que, se o réu não contestar a ação, será considerado revel e presumir-se-ão verdadeiras as alegações de fato formuladas pelo autor. A revelia produzirão esse efeito mesmo se","o":["as alegações de fato formuladas pelo autor forem inverossímeis.","houver litisconsórcio passivo e algum dos réus contestar a ação.","o réu apresentar contestação intempestiva, mas antes do julgamento da ação.","o litígio versar sobre direitos indisponíveis.","as alegações de fato formuladas pelo autor estiverem em contradição com a prova constante dos autos."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024 • TEC 3228695","source":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3228695","year":2024,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1071915","sourceQuestionId":"1071915","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento, o juiz","o":["exerce o poder de polícia, incumbindo-lhe ordenar que se retirem da sala de audiência quaisquer pessoas que se comportarem inconvenientemente.","só deverá tentar conciliar as partes se não tiver havido prévia audiência de conciliação, ou se alguma delas informar, por ocasião da abertura dos trabalhos, que pretende formular proposta de acordo.","somente poderá proferir sentença se todas as partes e o Ministério Público, nos feitos dos quais participar, concordarem em apresentar suas alegações finais oralmente ou dispensarem a sua apresentação.","não poderá obstar os advogados ou o Ministério Público de intervir ou apartear enquanto depuserem as testemunhas, ainda que sem a sua licença.","poderá, independentemente da concordância das partes, cindir a produção da prova oral, tomando o depoimento das testemunhas presentes e designando outra data para a oitiva das ausentes."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019 • TEC 1071915","source":"FCC - TJ TRF3/TRF 3/Administrativa/\"Sem Especialidade\"/2019","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1071915","year":2019,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3355405","sourceQuestionId":"3355405","t":"cpc-m11","moduleId":"cpc-m11","q":"Rafael compareceu à Defensoria Pública do Estado e afirmou desconhecer um contrato bancário firmado em seu nome. Durante o atendimento, ele alegou que a assinatura aposta no contrato é parecida, mas não é sua. Em eventual demanda judicial que questione a autenticidade da rubrica, de acordo com tese firmada em tema repetitivo pelo Superior Tribunal de Justiça,","o":["o pedido deverá ser julgado improcedente, caso o contrato tenha sido firmado por instituição financeira com natureza jurídica de direito público.","o ônus da prova caberá à instituição bancária apenas se presentes os requisitos da inversão do ônus da prova previstos no coe.","consoante com as peculiaridades do caso concreto e verossimilhança das alegações, caberá ao juiz fixar a distribuição do ônus da prova.","o ônus da prova caberá a Rafael, pois foi ele quem arguiu a falsidade da assinatura.","caberá à instituição financeira o ônus de provar a autenticidade da assinatura aposta no contrato."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AnaDP (DPE SP)/DPE SP/2025 • TEC 3355405","source":"FCC - AnaDP (DPE SP)/DPE SP/2025","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Procedimento Comum","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3355405","year":2025,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670671","sourceQuestionId":"3670671","t":"cpc-m11","moduleId":"cpc-m11","q":"A respeito dos honorários advocatícios sucumbenciais, é correto afirmar:","o":["Serão fixados por apreciação equitativa quando inestimável, irrisório ou excessivo o proveito econômico da demanda.","Quando fixados contra a Fazenda Pública, não poderão ser executados por meio de requisição de pequeno valor (RPV) se o crédito principal só puder ser exigido por meio de precatório.","Se o autor optar por realizar a substituição do réu, diante da alegação de ilegitimidade ad causam formulada em contestação, pagará honorários sucumbenciais, que serão fixados entre 3 e 5 por cento do valor da causa, desde que não irrisório.","A desistência da ação, se for total, enseja a fixação de honorários sucumbenciais a serem pagos pelo autor, mas, se for parcial, não incidem os honorários.","Se não houver requerimento de sua fixação na petição inicial, somente por ação autônoma poderá o advogado pleiteá-los."],"a":2,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670671","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670671","year":2025,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3554464","sourceQuestionId":"3554464","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, na contestação","o":["o réu deve, antes do mérito, alegar a ocorrência de prescrição, cujo reconhecimento acarreta a extinção do processo sem resolução de mérito.","é defeso ao réu alegar a incompetência absoluta ou relativa.","incumbe ao réu manifestar-se sobre as alegações de fato constantes da petição inicial, presumindo-se verdadeiras as não impugnadas, inclusive se a seu respeito não for admissível a confissão.","é lícito ao réu propor reconvenção para manifestar pretensão própria, conexa com a ação principal ou com o fundamento da defesa.","o réu deve, antes do mérito, alegar a ocorrência de coisa Julgada, cujo reconhecimento acarreta a extinção do processo com resolução de mérito."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025 • TEC 3554464","source":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3554464","year":2025,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2850453","sourceQuestionId":"2850453","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a revelia","o":["impede que o juiz determine a produção de provas.","não impede que o revel intervenha no processo.","induz presunção absoluta de veracidade das alegações de fato formuladas pelo autor, ainda que o litígio verse sobre direitos indisponíveis.","induz presunção relativa de veracidade das alegações de fato formuladas pelo autor, ainda que o litígio verse sobre direitos indisponíveis.","impõe o julgamento antecipado do mérito."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023 • TEC 2850453","source":"FCC - TJ TRT21/TRT 21/Administrativa/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2850453","year":2023,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-789028","sourceQuestionId":"789028","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento,","o":["uma vez instalada, o juiz tentará conciliar as partes, salvo se anteriormente tenha havido o emprego de outros métodos de solução consensual de conflitos, como a mediação e a arbitragem.","as provas orais serão produzidas em ordem peremptória, após o depoimento pessoal das partes.","sua unicidade e intermitência obsta que seja adiada, salvo apenas a hipótese de convenção das partes, em que será possível o adiamento por uma única vez.","enquanto depuserem o perito, os assistentes técnicos, as partes e as testemunhas, não poderão os advogados e o Ministério Público intervir ou apartear, sem licença do juiz.","encerrado o debate ou oferecidas as razões finais, o juiz proferirá sentença de imediato ou, excepcionalmente, se complexas as questões, no prazo de 15 dias."],"a":3,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019 • TEC 789028","source":"FCC - Ana Fom (AFAP)/AFAP/Advogado/2019","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/789028","year":2019,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2390176","sourceQuestionId":"2390176","t":"cpc-m11","moduleId":"cpc-m11","q":"Rita, idosa e aposentada, recebeu descontos em sua aposentadoria, em razão da realização de empréstimos consignados, os quais afirma desconhecer, pois não fez qualquer contratação de empréstimo. A Defensoria Pública propôs ação declaratória de inexistência do débito, ao passo que a instituição bancária demandada contestou e apresentou contrato que alega ter sido assinado por Rita. Essa, por seu turno, impugna a autenticidade da assinatura. Nesta hipótese, em conformidade com o entendimento firmado pelo Superior Tribunal de Justiça,","o":["cabe ao consumidor/autor o ônus de provar essa falsidade da assinatura, uma vez que foi por ele alegada e tal prova deve ser feita por intermédio de perícia grafotécnica ou mediante os meios de prova legais ou moralmente legítimos.","cabe à instituição financeira/ré o ônus de provar essa autenticidade, por intermédio de perícia grafotécnica ou mediante os meios de prova legais ou moralmente legítimos.","caberá ao juiz verificar as circunstâncias de cada caso concreto para aferir as peculiaridades e circunstâncias específicas e, assim, distribuir o ônus da prova a quem tem melhores condições de produzi-la.","cabe ao consumidor/autor o ônus de provar essa autenticidade, porém haverá inversão do ônus do custeio de eventual perícia grafotécnica, cujos custos deverão ser arcados pela instituição financeira/ré.","cabe à instituição financeira/ré o ônus de provar essa autenticidade, por intermédio de perícia grafotécnica, único meio de prova adequado para dirimir tal controvérsia."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2023 • TEC 2390176","source":"FCC - DP SP/DPE SP/2023","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Procedimento Comum","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2390176","year":2023,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3228697","sourceQuestionId":"3228697","t":"cpc-m11","moduleId":"cpc-m11","q":"Em ação movida por Paulo contra Maria, esta apresentou contestação alegando, em preliminar, não ser parte legitima. Alegou, ainda, que a ação devia ter sido proposta contra Fernanda, única legitimada a figurar no polo passivo. Intimado a se manifestar sobre a contestação, Paulo concordou com a preliminar, pleiteando a substituição de Maria por Fernanda, com o prosseguimento do feito. Nesse caso, de acordo com o Código de Processo Civil, verificando a procedência da preliminar, o juiz deverá","o":["deferir a substituição da ré, sem extinguir o processo, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, bem como a pagar honorários em favor do advogado dela.","extinguir o processo e indeferir a substituição da ré, porquanto inadmissível depois da contestação, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, mas não o condenará ao pagamento de honorários em favor do advogado dela.","deferir a substituição da ré, sem extinguir o processo, além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, mas não o condenará ao pagamento de honorários em favor do advogado dela.","deferir a substituição da ré, sem extinguir o processo; contudo, não deverá condenar Paulo a reembolsar as despesas suportadas por Maria ou a pagar honorários em favor do advogado dela, salvo se identificar ma -fé.","extinguir o processo e indeferir a substituição da ré, porquanto inadmissível depois da contestação; além disso, deverá condenar Paulo a reembolsar as despesas suportadas por Maria, bem como a pagar honorários em favor do advogado dela."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024 • TEC 3228697","source":"FCC - AJ TRT20/TRT 20/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Da Contestação (arts. 335 a 342)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3228697","year":2024,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126491","sourceQuestionId":"3126491","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o Código de Processo Civil, a desistência da ação","o":["independe, em qualquer caso, do consentimento do réu.","implica, quando homologada, extinção do processo com resolução de mérito.","produz efeitos independentemente de homologação judicial.","pode ser apresentada apenas até a contestação.","não obsta o prosseguimento do processo em relação à reconvenção."],"a":4,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126491","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Reconvenção (art. 343)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126491","year":2024,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2038258","sourceQuestionId":"2038258","t":"cpc-m11","moduleId":"cpc-m11","q":"De acordo com o art. 344, do Código de Processo Civil, se o réu não contestar a ação, será considerado revel e, por consequência, serão presumidas verdadeiras as alegações de fato formuladas pelo autor. Tal efeito incidirá","o":["somente se houver verossimilhança nas alegações autorais e não estiver em contradição com nenhuma prova produzida nos autos.","em uma ação com pedido de declaração da paternidade em que o réu deixou de contestar.","ainda que algum corréu tenha contestado o pedido do autor, diante do princípio da autonomia dos litisconsortes.","mesmo se o réu for citado por edital e houver apresentação de contestação por negativa geral pelo defensor público, por ausência de impugnação específica dos fatos.","salvo exceções legais, inviabilizando a atividade probatória do réu revel."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP CE/DPE CE/2022 • TEC 2038258","source":"FCC - DP CE/DPE CE/2022","subject":"Direito Processual Civil - Da Revelia (arts. 344 a 346)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2038258","year":2022,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-732966","sourceQuestionId":"732966","t":"cpc-m11","moduleId":"cpc-m11","q":"Na audiência de instrução e julgamento serão produzidas as provas orais, ouvindo-se","o":["preferencialmente nesta ordem: o perito e os assistentes técnicos; o autor e o réu; e as testemunhas arroladas pelo autor e pelo réu.","obrigatoriamente nesta ordem: o perito e os assistentes técnicos; o autor e o réu; e as testemunhas arroladas pelo autor e pelo réu.","preferencialmente nesta ordem: o autor e o réu; as testemunhas arroladas pelo autor e pelo réu; e o perito e os assistentes técnicos.","obrigatoriamente nesta ordem: o autor e o réu; as testemunhas arroladas pelo autor e pelo réu; e o perito e os assistentes técnicos.","obrigatoriamente nesta ordem: o autor e o réu; o perito e os assistentes técnicos; e as testemunhas arroladas pelo autor e pelo réu."],"a":0,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2018 • TEC 732966","source":"FCC - Ana Min (MPE PE)/MPE PE/Jurídica/2018","subject":"Direito Processual Civil - Da Audiência de Instrução e Julgamento (arts. 358 a 368)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/732966","year":2018,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2712712","sourceQuestionId":"2712712","t":"cpc-m11","moduleId":"cpc-m11","q":"Como matéria de defesa, a usucapião pode ser alegada","o":["gerando tão somente efeito indenizatório.","não somente em ação reivindicatória.","apenas se relativa à disputa de imóvel rural.","somente em ação reivindicatória.","somente em ação demarcatória."],"a":1,"e":"Tema classificado no Módulo 11: Defesa, revelia, saneamento e julgamento conforme o estado. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023 • TEC 2712712","source":"FCC - Ana JD (DPE AM)/DPE AM/Ciências Jurídicas/2023","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Procedimento Comum","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2712712","year":2023,"classificationReason":"Defesa, revelia, saneamento ou julgamento no procedimento comum.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883940","sourceQuestionId":"3883940","t":"cpc-m12","moduleId":"cpc-m12","q":"Em uma ação individual de indenização por danos morais e estéticos movida pela Defensoria Pública contra uma grande mineradora em razão de desastre ambiental em Mato Grosso, o Defensor Público alega que o assistido (ribeirinho) não possui condição técnica e financeira de produzir prova pericial complexa sobre o nexo de causalidade entre os resíduos encontrados no rio e as enfermidades desenvolvidas. Ao sanear o processo, o juiz decide aplicar a distribuição dinâmica do ônus da prova. Sobre essa decisão, aplicando-se as normas do CPC,","o":["a inversão do ônus da prova por convenção das partes é admitida pelo CPC apenas quando não houver participação da Defensoria Pública no feito.","a distribuição dinâmica do ônus da prova é vedada em ações que envolvam responsabilidade civil ambiental, devendo o autor provar o fato constitutivo e o réu o fato impeditivo em todos os casos.","caso o juiz inverta o ônus da prova na própria sentença, sem aviso prévio, a decisão será válida em razão do princípio do livre convencimento motivado.","a mineradora, ao receber o novo encargo probatório, fica obrigada a arcar antecipadamente com os honorários do perito judicial, sob pena de confissão ficta quanto aos fatos alegados.","o magistrado pode atribuir o ônus da prova de modo diverso quando verificar a excessiva dificuldade de cumprir o encargo ou a maior facilidade de obtenção da prova pela parte contrária, devendo fazê-lo em decisão fundamentada e conceder à parte o direito de se desincumbir do ônus que lhe foi atribuído."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883940","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883940","year":2026,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2975465","sourceQuestionId":"2975465","t":"cpc-m12","moduleId":"cpc-m12","q":"Com relação às provas, considere: I. Cabe à parte requerer o depoimento pessoal da outra parte, a fim de que esta seja interrogada na audiência de instrução e julgamento, sendo vedado ao juiz ordená-lo de ofício. II. Nas ações que versarem sobre bens imóveis ou direitos reais sobre imóveis alheios, a confissão de um cônjuge ou companheiro não valerá sem a do outro, salvo se o regime de casamento for o de separação absoluta de bens. III. O juiz não pode ordenar, em nenhuma hipótese, a requerimento da parte, a exibição integral dos livros empresariais e dos documentos do arquivo na sucessão por morte de sócio. Em conformidade com o Código de Processo Civil, está correto o que se afirma em","o":["II, apenas.","I e III, apenas.","I, II e III.","I, apenas.","III, apenas."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Adv (CETESB)/CETESB/2024 • TEC 2975465","source":"FCC - Adv (CETESB)/CETESB/2024","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2975465","year":2024,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488268","sourceQuestionId":"2488268","t":"cpc-m12","moduleId":"cpc-m12","q":"Acerca da força probante dos documentos, considere: I. Considera-se autêntico o documento quando não houver impugnação da parte contra quem foi produzido. II. O documento público faz prova apenas da sua formação e não dos fatos que o escrivão, o chefe de secretaria, o tabelião ou o servidor declarar que ocorreram em sua presença. III. O documento feito por oficial público incompetente não possui eficácia, ainda que subscrito pelas partes. IV. A escrituração contábil é indivisível, e, se, dos fatos que resultam dos lançamentos, uns são favoráveis ao interesse de seu autor e outros lhe são contrários, ambos serão considerados em conjunto, como unidade. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["I e IV.","II e III.","II e IV.","III e IV.","I e II."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488268","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488268","year":2025,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3853442","sourceQuestionId":"3853442","t":"cpc-m12","moduleId":"cpc-m12","q":"Na produção da prova testemunhal,","o":["a intimação será feita pela via judicial quando a testemunha houver sido arrolada pelo Ministério Público ou pela Defensoria Pública.","se o juiz for arrolado como testemunha deverá, em qualquer caso, e obrigatoriamente, declarar-se impedido.","o juiz inquirirá as testemunhas conjuntamente na mesma sala, iniciando-se as perguntas àquelas arroladas pelo autor e depois às do réu.","as perguntas serão formuladas às testemunhas de maneira indireta, por intermédio da autoridade judiciária.","depois de apresentado o rol nos autos do processo, não é permitido substituir as testemunhas."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026 • TEC 3853442","source":"FCC - Tec Min (MPE AP)/MPE AP/Apoio Administrativo/2026","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3853442","year":2026,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488263","sourceQuestionId":"2488263","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a confissão","o":["pode ocorrer judicial ou extrajudicialmente.","extrajudicial só pode ser realizada por escrito.","é, em regra, divisível.","deve ser sempre espontânea.","vale como tal e gera efeitos ainda que recaia sobre direitos indisponíveis."],"a":0,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488263","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488263","year":2025,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3930557","sourceQuestionId":"3930557","t":"cpc-m12","moduleId":"cpc-m12","q":"Com base nas disposições do Código de Processo Civil, um perito-contador nomeado em um processo judicial, após a ciência de sua nomeação, deve","o":["apresentar, no prazo de 15 dias, resumo geral do trabalho a ser realizado, com as minutas de provas pré-preenchidas.","prestar compromisso formal nos autos para validar o encargo que lhe foi cometido, sob pena de nulidade da perícia realizada.","notificar as partes sobre sua nomeação, que deve ser aceita. Eventual discordância ocorre em sede de recurso processual.","apresentar, em 5 dias, proposta de honorários.","arbitrar os honorários periciais, após a manifestação das partes."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ALegis (ALMS)/ALMS/Contador/2026 • TEC 3930557","source":"FCC - ALegis (ALMS)/ALMS/Contador/2026","subject":"Direito Processual Civil - Da Prova Pericial (arts. 464 a 480)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3930557","year":2026,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488262","sourceQuestionId":"2488262","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a produção antecipada de provas","o":["tem cabimento apenas se houver fundado receio de que venha a tomar-se impossível ou muito difícil a verificação de certos fatos na pendência da ação.","dispensa, em todo e qualquer caso, a citação.","é de competência do foro do domicílio do autor.","previne a competência do juízo para a ação que venha a ser proposta.","não admite, em regra, defesa ou recurso, salvo contra decisão que indeferir totalmente a produção da prova pleiteada pelo requerente originário."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488262","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Produção Antecipada da Prova (arts. 381 a 383)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488262","year":2025,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3227470","sourceQuestionId":"3227470","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, o depoimento pessoal","o":["implica o dever de depor sobre todos os fatos que lhe forem perguntados, sem exceção.","pode ser assistido pela parte que ainda não foi ouvida.","prescinde, para aplicação da pena de confesso, de prévia intimação pessoal.","deve ser requerido pela própria parte, para oitiva dela própria, se desejar expor pessoalmente os fatos.","pode ser colhido por meio de videoconferência, inclusive durante a audiência de instrução e julgamento, se a parte residir em comarca diversa daquela onde tramita à processo."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3227470","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Do Depoimento Pessoal (arts. 385 a 388)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3227470","year":2024,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373318","sourceQuestionId":"373318","t":"cpc-m12","moduleId":"cpc-m12","q":"A existência e o modo de existir de algum fato podem ser atestados ou documentados","o":["por qualquer servidor público, dada a fé pública dos atos por ele praticados.","por simples declaração do interessado, que se presume verdadeira.","somente pelo registro de documento particular em cartório de títulos e documentos.","por tabelião em ata notarial, a requerimento do interessado.","apenas por escritura pública de declaração, lavrada em notas de tabelião."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373318","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Da Ata Notarial (art. 384)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373318","year":2015,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-2154181","sourceQuestionId":"2154181","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o disposto no Código de Processo Civil, a inspeção judicial","o":["é ato exclusivo do oficial de justiça, que a realizará com ou sem auxílio de perito, de ofício ou a requerimento das partes.","poderá ser realizada, pelo Juiz, sempre a requerimento das partes e com auxílio de perito.","é ato exclusivo do oficial de justiça, que a realizará sempre com auxílio de perito, de ofício ou a requerimento das partes.","poderá ser realizada, pelo Juiz, de ofício ou a requerimento das partes, com ou sem auxílio de perito.","é ato exclusivo do oficial de justiça, que a realizará com ou sem auxílio de perito e apenas a requerimento das partes."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Of Jus (TJ CE)/TJ CE/2022 • TEC 2154181","source":"FCC - Of Jus (TJ CE)/TJ CE/2022","subject":"Direito Processual Civil - Da Inspeção Judicial (arts. 481 a 484)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154181","year":2022,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937740","sourceQuestionId":"3937740","t":"cpc-m12","moduleId":"cpc-m12","q":"Márcio ajuizou ação de modificação de guarda em face de Joana, maior e capaz. Na petição inicial, o autor informou que a ré não fornecia os cuidados devidos ao filho de 10 anos e, por isso, a guarda fixada anteriormente em favor da mãe deveria ser modificada para que o pai passasse a exercê-la unilateralmente. Joana foi pessoalmente citada, mas não contestou a ação dentro do prazo legal. Nessa situação, de acordo com o Código de Processo Civil,","o":["a autoridade judicial ordenará, de ofício, as provas a serem produzidas, não havendo necessidade de intimação do Ministério Público e/ou da Defensoria Pública.","presumir-se-ão verdadeiras as alegações de fato formuladas por Márcio, devendo a autoridade judicial proceder ao julgamento antecipado do mérito.","a autoridade judicial abrirá prazo para que o autor especifique as provas que pretende produzir, bem como intimará o Ministério Público a se manifestar como fiscal da ordem jurídica.","a Defensoria Pública deverá ser intimada para atuar como curadora especial de Joana, enquanto esta permanecer revel nos autos.","Joana poderá intervir posteriormente no processo, desde que o faça antes da prolação da sentença."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937740","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Disposições Gerais (arts. 369 a 380)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937740","year":2026,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2021315","sourceQuestionId":"2021315","t":"cpc-m12","moduleId":"cpc-m12","q":"Analise as proposições abaixo, acerca da prova: I. O Juiz que tiver conhecimentos técnicos poderá dispensar a indicação de perito e conduzir, ele próprio, a prova pericial. II. É vedado ao juiz admitir o depoimento de testemunhas menores, impedidas ou suspeitas. III. A inspeção judicial pode ser determinada de ofício. IV. As partes podem, a qualquer tempo, juntar aos autos documentos novos, quando destinados a fazer prova de fatos ocorridos depois dos articulados ou para contrapô-los aos que foram produzidos nos autos. Está correto o que se afirma APENAS em","o":["II e III.","II e IV.","I e III.","I e II.","III e IV."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Proc (PGE AM)/PGE AM/2022 • TEC 2021315","source":"FCC - Ana Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Tópicos Mesclados do Capítulo \"das Provas\"","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2021315","year":2022,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2488269","sourceQuestionId":"2488269","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, os livros empresariais provam","o":["contra seu autor, que não pode alegar fatos contrários a seu conteúdo.","somente na liquidação de sociedade.","apenas em favor de seu autor.","contra seu autor, que pode, todavia, demonstrar, por todos os meios permitidos em direito, que os lançamentos não correspondem à verdade dos fatos.","a favor de quaisquer das partes, ainda que não cumpram os requisitos exigidos por lei."],"a":3,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025 • TEC 2488269","source":"FCC - AMCI (CGM SP)/Pref SP/Correição/2025","subject":"Direito Processual Civil - Da Prova Documental (arts. 405 a 438)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2488269","year":2025,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126657","sourceQuestionId":"3126657","t":"cpc-m12","moduleId":"cpc-m12","q":"Em relação à prova testemunhal, dispõe o Código de Processo Civil que","o":["a inquirição das testemunhas é realizada sempre por intermédio do juiz, que não admitirá perguntas diretas ou que possam induzir a resposta.","a intimação das testemunhas deve ser realizada, via de regra, por carta precatória ou mandado, conforme residam ou não na comarca em que tramita o processo.","a parte pode requerer a substituição imotivada da testemunha, desde que o faça no prazo de 15 dias da decisão saneadora.","o juiz inquirirá primeiro as testemunhas do autor e depois as do réu, não podendo alterar esta ordem, ainda que a pedido ou com a concordância das partes.","o juiz poderá inquirir a testemunha tanto antes quanto depois da inquirição feita pelas partes."],"a":4,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126657","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Prova Testemunhal (arts. 442 a 463)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126657","year":2024,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2152368","sourceQuestionId":"2152368","t":"cpc-m12","moduleId":"cpc-m12","q":"De acordo com o Código de Processo Civil, a confissão judicial","o":["do cônjuge, nas ações que versarem sobre bens imóveis, só valerá se tiver havido também a do outro, independentemente do regime de bens.","não pode ser provocada.","é irrevogável, mas será ineficaz se feita por quem não era capaz de dispor do direito a que se referem os fatos confessados.","faz prova contra os confitentes e prejudica os litisconsortes.","é, em regra, divisível, podendo a parte que a quiser invocar como prova aceitá-la no tópico que a beneficiar e rejeitá-la no que lhe for desfavorável."],"a":2,"e":"Tema classificado no Módulo 12: Provas: teoria geral e meios em espécie. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022 • TEC 2152368","source":"FCC - AJ (TJ CE)/TJ CE/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Da Confissão (arts. 389 a 395)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2152368","year":2022,"classificationReason":"Teoria geral ou meio de prova expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3821952","sourceQuestionId":"3821952","t":"cpc-m13","moduleId":"cpc-m13","q":"Em conformidade com o Código de Processo Civil, publicada uma sentença, o juiz só poderá alterá-la","o":["para corrigir-lhe, somente de ofício, apenas erros de cálculo, e por meio de embargos de declaração.","para corrigir-lhe, somente a requerimento da parte, apenas inexatidões materiais, e por meio de embargos de declaração.","para corrigir-lhe, de ofício ou a requerimento da parte, inexatidões materiais ou erros de cálculo; e por meio de embargos de declaração.","para corrigir-lhe, somente a requerimento da parte, apenas erros de cálculo, e por meio de embargos de declaração.","somente por meio de embargos de declaração."],"a":2,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821952","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821952","year":2026,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3821959","sourceQuestionId":"3821959","t":"cpc-m13","moduleId":"cpc-m13","q":"Determinada sentença condenou ao pagamento de quantia ilíquida. Nessa situação, considerando que há necessidade de alegar e provar fato novo, de acordo com o Código de Processo Civil, deve-se proceder à sua liquidação, a requerimento do credor ou do devedor,","o":["pelo procedimento comum, sendo que na liquidação é vedado discutir de novo a lide ou modificar a sentença que a julgou.","por arbitramento, sendo que, quando a apuração do valor depender apenas de cálculo aritmético, o credor poderá promover, desde logo, o cumprimento da sentença.","pelo procedimento comum, de acordo com o qual o juiz intimará as partes para a apresentação de pareceres ou documentos elucidativos, no prazo fixo de 15 dias, sendo possível nomear perito, ainda que possa decidir de plano, observando-se, no que couber, o procedimento da prova pericial.","por arbitramento, de acordo com o qual o juiz determinará a intimação do requerido, na pessoa de seu advogado ou da sociedade de advogados a que estiver vinculado, para, querendo, apresentar contestação no prazo de 15 dias.","por arbitramento, de acordo com o qual o juiz intimará as partes para a apresentação de pareceres ou documentos elucidativos, no prazo que fixar, e, caso não possa decidir de plano, nomeará perito, observando-se, no que couber, o procedimento da prova pericial."],"a":0,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821959","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821959","year":2026,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937762","sourceQuestionId":"3937762","t":"cpc-m13","moduleId":"cpc-m13","q":"À luz do regime da coisa julgada coletiva e da prevenção de decisões conflitantes,","o":["a declaração incidental de invalidade normativa em processo coletivo não integra o comando decisório, razão pela qual jamais produzirá estabilização apta a impedir demanda posterior.","a pluralidade de legitimados em ações diversas impede litispendência e coisa julgada, pois não há identidade subjetiva entre substitutos processuais, sendo sempre possível nova ação idêntica.","a coisa julgada coletiva pode impedir nova demanda coletiva com mesmo núcleo fático-jurídico e mesmo resultado prático pretendido, devendo o julgador avaliar identidade substancial de pedidos e causas, além do risco de decisões contraditórias.","a eficácia territorial das decisões coletivas sempre bloqueia qualquer discussão em outro juízo, ainda que a lesão seja unitária e o resultado prático buscado seja idêntico, considerando a sistemática normativa processual coletiva.","a existência de interesse público qualificado autoriza multiplicação de ações coletivas idênticas, pois a concorrência entre legitimados é instrumento de aprimoramento deliberativo."],"a":2,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937762","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937762","year":2026,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3956202","sourceQuestionId":"3956202","t":"cpc-m13","moduleId":"cpc-m13","q":"Cláudio foi vítima de crime de roubo do seu telefone celular e na sentença penal condenatória foi fixada indenização no valor de R$ 2.000,00. A sentença penal transitou em julgado. O valor do telefone roubado e não recuperado era superior ao valor fixado na sentença. No caso, a sentença penal condenatória","o":["é passível de cumprimento de sentença na esfera cível, que executará o valor fixado no título judicial, após o que, sucessivamente, será necessário o ajuizamento de nova ação de conhecimento para o estabelecimento de indenização em valor correto.","não será passível de cumprimento de sentença na esfera cível, pois o valor deverá ser executado pelo juízo que proferiu o título executivo.","não será passível de cumprimento de sentença na esfera cível, pois o quantum debeatur foi fixado de forma genérica, a demandar nova ação de conhecimento para o estabelecimento de indenização em valor correto.","é passível de cumprimento de sentença na esfera cível, que executará o valor fixado no título judicial, após o que, sucessivamente, poderá formular liquidação de sentença por arbitramento a fim de complementar o valor do dano material sofrido.","é passível de cumprimento de sentença na esfera cível, que executará o valor fixado no título judicial concomitantemente ao ajuizamento de liquidação de sentença por procedimento comum a fim de complementar o valor do dano material sofrido."],"a":4,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956202","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956202","year":2026,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3375489","sourceQuestionId":"3375489","t":"cpc-m13","moduleId":"cpc-m13","q":"Com relação ao regime jurídico aplicável à produção de coisa julgada no Direito Processual Civil:","o":["A verdade dos fatos, quando estabelecida como fundamento da sentença, faz coisa julgada.","A superveniência de alteração legislativa aplicável a uma relação jurídica de trato continuado faz com que a parte sucumbente possa propor nova açao identica voltada à modificacao de acordão ja transitado em julgado que dispunha, no mérito, sobre o regime jurídico que deveria ser respeitado pelos litigantes.","A decisão proferida em ação civil pública proposta com o intuito de defesa de direitos individuais homogêneos, uma vez que decorrentes de origem comum, produz coisa julgada inter partes.","Segundo o Código de Processo Civil, a produção de coisa julgada em relação à decisão proferida, de maneira expressa e incidental, em relação a uma questão prejudicial de mérito fica condicionada à circunstância de o órgão julgador ser detentor de competência territorial para o seu julgamento como questão principal.","Ocorre ofensa à coisa julgada nos casos em que a realização da liquidação da sentença se dá de forma diversa daquela que houver nela sido estabelecida."],"a":1,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375489","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375489","year":2025,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3554465","sourceQuestionId":"3554465","t":"cpc-m13","moduleId":"cpc-m13","q":"Segundo o Código de Processo Civil, a liquidação de sentença","o":["pelo procedimento comum ocorre a requerimento do credor ou do devedor quando a sentença condenar ao pagamento de quantia ilíquida e houver necessidade de alegar e provar fato novo, sendo vedado rediscutir a lide ou modificar a sentença que a julgou.","pelo procedimento comum dispensa a apresentação de contestação.","por arbitramento deve ser instaurada de oficio quando a sentença condenar ao pagamento de quantia ilíquida e houver necessidade de alegar e provar fato novo, caso em que poderá ser rediscutida a lide e modificada a sentença que a julgou.","não pode ocorrer na pendência de recurso.","por arbitramento deve ser instaurada de oficio quando a sentença condenar ao pagamento de quantia ilíquida e houver necessidade de alegar e provar fato novo, sendo vedado rediscutir a lide ou modificar a sentença que a julgou."],"a":0,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025 • TEC 3554465","source":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3554465","year":2025,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3571730","sourceQuestionId":"3571730","t":"cpc-m13","moduleId":"cpc-m13","q":"De acordo com o Código de Processo Civil, a decisão que julgar total ou parcialmente o mérito tem força de lei nos limites da questão principal expressamente decidida. Essa mesma regra também se aplica à resolução de questão prejudicial, decidida expressa e incidentemente no processo, se:","o":["dessa resolução independer o julgamento do mérito; a seu respeito tiver havido oportunidade de contraditório prévio, inclusive no caso de revelia; o juízo tiver competência em razão da matéria para resolvê-la como questão principal, ainda que não tenha competência em razão da pessoa; e inexistirem restrições probatórias ou limitações à cognição que impeçam o aprofundamento da análise da questão prejudicial.","dessa resolução depender o julgamento do mérito; a seu respeito tiver havido contraditório prévio e efetivo, não se aplicando no caso de revelia; o juízo tiver competência em razão da matéria e da pessoa para resolvê-la como questão principal; e inexistirem restrições probatórias ou limitações à cognição que impeçam o aprofundamento da análise da questão prejudicial.","a seu respeito tiver havido oportunidade de contraditório, inclusive no caso de revelia; e o juízo tiver competência em razão da matéria e da pessoa para resolvê- la como questão principal, mesmo quando o julgamento do mérito não depender dessa resolução, desde que inexistam restrições probatórias ou limitações à cognição que impeçam o aprofundamento da análise da questão prejudicial.","dessa resolução depender o julgamento do mérito; a seu respeito tiver havido oportunidade de contraditório, inclusive no caso de revelia; e o juízo tiver competência territorial para resolvê-la, mesmo que existam restrições probatórias ou limitações à cognição que impeçam o aprofundamento da análise da questão prejudicial.","a seu respeito tiver havido contraditório prévio e efetivo, não se aplicando no caso de revelia; e o juízo tiver competência em razão da matéria e da pessoa para resolvê-la como questão principal, mesmo quando o julgamento do mérito não depender dessa resolução ou que existam restrições probatórias ou limitações à cognição que impeçam o aprofundamento da análise da questão prejudicial."],"a":1,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025 • TEC 3571730","source":"FCC - AJ TRT2/TRT 2/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3571730","year":2025,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670682","sourceQuestionId":"3670682","t":"cpc-m13","moduleId":"cpc-m13","q":"A liquidação de sentença","o":["é dispensável, enquanto etapa processual, nos casos em que a apuração do valor depender apenas de cálculo aritmético, a cargo do credor.","poderá ser realizada na pendência de recurso, se este for recebido com efeito suspensivo.","enseja, quando realizada pelo procedimento comum, a citação do requerido para, querendo, apresentar contestação no prazo de 15 (quinze) dias.","por arbitramento depende da produção de prova pericial ou oral, a critério do juiz.","sempre terá lugar quando o autor tiver formulado, no início do processo, pedido genérico, pois nesse caso é vedada decisão final de mérito líquida."],"a":0,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670682","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670682","year":2025,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670620","sourceQuestionId":"3670620","t":"cpc-m13","moduleId":"cpc-m13","q":"A remessa necessária","o":["não será exigida se a sentença estiver em consonância com entendimento firmado em incidente de resolução de demandas repetitivas.","deve ser observada em ações movidas contra empresas públicas.","é aplicável contra sentença que julga os embargos à execução fiscal, acolhendo ou rejeitando-os.","só deverá ser observada em ação movida contra qualquer Município, se o conteúdo econômico do processo for superior a 100 salários mínimos.","é aplicável contra acórdão que julga recurso de apelação em desfavor da Fazenda Pública, por maioria de votos, justificada a medida pela falta de unanimidade no julgamento."],"a":0,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670620","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670620","year":2025,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2022856","sourceQuestionId":"2022856","t":"cpc-m13","moduleId":"cpc-m13","q":"Uma ação indenizatória movida por sociedade empresária contra o Estado Y é julgada procedente, para condená-lo a indenizar os prejuízos decorrentes de demolição parcial de imóvel de sua propriedade, decorrente de falhas na execução de obras públicas em local próximo, a serem apurados em liquidação de sentença pelo procedimento comum, como expressamente indicado na parte dispositiva da decisão. O Estado interpõe recurso de apelação. Imediatamente após encaminhamento dos autos digitais à segunda instância, a autora dá início à etapa de liquidação de sentença, requerendo que ela seja feita, dadas as peculiaridades do caso, por arbitramento. Nesse caso,","o":["mesmo com efeito suspensivo do recurso de apelação, é admitida a liquidação, mas não a alteração da forma de sua realização, sob pena de indevida afronta à própria decisão liquidanda.","mesmo com efeito suspensivo do recurso de apelação, é admitida a liquidação, como também a alteração da forma de sua realização, desde que mais adequada, sem que se cogite de ofensa a esse ponto da decisão liquidanda.","o efeito suspensivo do recurso de apelação impede a liquidação, mas, com o trânsito em julgado, será possível sua realização, com alteração da forma indicada na sentença, desde que mais adequada, e sem que se cogite de ofensa a esse ponto da decisão liquidanda.","o efeito suspensivo do recurso de apelação impede a liquidação, mas, com o trânsito em julgado, será possível sua realização, ainda que apenas da forma prevista na própria decisão liquidanda, para não afrontá-la.","a liquidação será possível, na pendência de recurso, desde que o interessado ofereça caução (mesmo que real), permitida a alteração da forma de sua realização, desde que mais adequada, sem que se cogite de ofensa a esse ponto da decisão liquidanda."],"a":1,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AM)/PGE AM/2022 • TEC 2022856","source":"FCC - Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2022856","year":2022,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126501","sourceQuestionId":"3126501","t":"cpc-m13","moduleId":"cpc-m13","q":"De acordo com o Código de Processo Civil, a extinção do processo por abandono","o":["impede que o autor alegue em defesa a matéria que foi objeto da ação.","deve ser precedida de intimação pessoal para suprimento da falta, no prazo de 5 dias.","independente, em qualquer caso, de requerimento do réu, tratando-se de matéria cognoscível de ofício.","acarreta a extinção do processo com resolução de mérito.","verifica-se quando a causa permanece paralisada, por pelo menos 90 dias, em razão de fato imputável à parte ou a demora no cumprimento das decisões judiciais."],"a":1,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126501","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126501","year":2024,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2154179","sourceQuestionId":"2154179","t":"cpc-m13","moduleId":"cpc-m13","q":"De acordo com o disposto no Código de Processo Civil, a liquidação de sentença","o":["impede o credor de promover a execução da sua parte líquida, enquanto não concluída.","não pode ser realizada na pendência de recurso.","não autoriza que se discuta de novo a lide, ainda que venha a ser processada pelo procedimento comum.","é procedimento obrigatório e prévio ao cumprimento, mesmo quando a apuração do valor depender apenas de cálculo aritmético.","admite a apresentação de contestação, para a qual o réu será citado pessoalmente."],"a":2,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Of Jus (TJ CE)/TJ CE/2022 • TEC 2154179","source":"FCC - Of Jus (TJ CE)/TJ CE/2022","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2154179","year":2022,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2340294","sourceQuestionId":"2340294","t":"cpc-m13","moduleId":"cpc-m13","q":"De acordo com o Código de Processo Civil, a desistência da ação pode ser apresentada","o":["somente até a sentença.","somente até a contestação.","somente até o saneamento do processo.","somente até a citação.","a qualquer tempo, inclusive depois da sentença."],"a":0,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023 • TEC 2340294","source":"FCC - AJ TRT18/TRT 18/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2340294","year":2023,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1818198","sourceQuestionId":"1818198","t":"cpc-m13","moduleId":"cpc-m13","q":"De acordo com o Código de Processo Civil, a liquidação de sentença","o":["exige, em todos os casos, nova citação do devedor.","observará o procedimento comum quando houver necessidade de alegar e provar fato novo.","somente será realizada por arbitramento se houver convenção das partes nesse sentido.","admite a rediscussão de todos os aspectos da lide.","não poderá ser realizada na pendência de recurso."],"a":1,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ Aux (TJ SC)/TJ SC/2021 • TEC 1818198","source":"FCC - TJ Aux (TJ SC)/TJ SC/2021","subject":"Direito Processual Civil - Da Liquidação de Sentença (arts. 509 a 512)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1818198","year":2021,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2456483","sourceQuestionId":"2456483","t":"cpc-m13","moduleId":"cpc-m13","q":"Há sentença com resolução de mérito quando esta","o":["homologar a desistência da ação após a apresentação de contestação pelo réu.","reconhecer a existência de perempção, de litispendência ou de coisa julgada.","verificar a ausência de pressupostos de constituição e de desenvolvimento válido e regular do processo.","acolher a alegação de existência de convenção de arbitragem ou quando o juízo arbitral reconhecer sua competência.","decidir, de ofício ou a requerimento, sobre a ocorrência de decadência ou prescrição."],"a":4,"e":"Tema classificado no Módulo 13: Sentença, remessa necessária, coisa julgada e liquidação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023 • TEC 2456483","source":"FCC - TM (MPE PB)/MPE PB/Sem Especialidade/2023","subject":"Direito Processual Civil - Da Sentença e Da Coisa Julgada (arts. 485 a 508)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2456483","year":2023,"classificationReason":"Sentença, coisa julgada ou liquidação expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883934","sourceQuestionId":"3883934","t":"cpc-m14","moduleId":"cpc-m14","q":"Na fase de impugnação ao cumprimento de sentença que condenou o Estado de Mato Grosso ao pagamento de verba remuneratória, a Procuradoria do Estado alega que o título é inexigível porque o STF declarou a inconstitucionalidade da lei que fundamentou a sentença condenatória. O CPC estabelece que essa alegação de “título fundado em lei inconstitucional”","o":["permite a suspensão do pagamento por tempo indeterminado, até que o Poder Legislativo revogue formalmente a lei inconstitucional.","é irrelevante após o trânsito em julgado da fase de conhecimento, prevalecendo a imutabilidade da coisa julgada em qualquer hipótese.","autoriza o juiz a anular a sentença de ofício, em razão da natureza absoluta da nulidade constitucional.","somente poderá ser arguida em sede de impugnação se o pronunciamento do STF tiver ocorrido antes do trânsito em julgado da sentença exequenda.","obriga a Defensoria Pública a desistir do cumprimento de sentença, sob pena de condenação por litigância de má-fé e multa."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883934","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883934","year":2026,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3670518","sourceQuestionId":"3670518","t":"cpc-m14","moduleId":"cpc-m14","q":"Uma autarquia foi condenada, por decisão transitada em julgado, a reajustar os vencimentos de determinado servidor, de acordo com certos critérios, observados índices de correção monetária e juros expressamente fixados no título judicial. Na fase de cumprimento da sentença, a autarquia, em sede de impugnação, requereu que ao caso fossem aplicados índices de correção monetária e incidissem juros de mora em conformidade com legislação e entendimento jurisprudencial fixado em sede de repercussão geral, pelo Supremo Tribunal Federal (STF), ambos posteriores ao trânsito em julgado do título executivo. Diante da Constituição Federal e da jurisprudência do STF, a pretensão da autarquia à adequação dos índices fixados na decisão transitada em julgado é","o":["admissível, em virtude da incidência apenas de legislação superveniente e desde que esta seja referente aos Índices pelos quais a Fazenda Pública atualiza e remunera seus créditos tributários, sob pena de ofensa ao princípio da isonomia.","admissível, em virtude da incidência de legislação ou de entendimento jurisprudencial do STF supervenientes, apenas em relação à correção monetária, sob pena de caracterização de confisco e consequente violação ao direito de propriedade.","admissível, em virtude da incidência de legislação ou de entendimento jurisprudencial do STF supervenientes, apenas em relação aos juros, uma vez que estes são efeitos continuados do ato decisório, configurando-se a pretensão a seu recebimento como situação jurídica pendente, atingida pelas normas supervenientes.","admissível, em virtude da incidência de legislação ou de entendimento jurisprudencial do STF supervenientes, tanto em relação à correção monetária, como em relação aos juros, inexistindo ofensa à garantia constitucional da coisa julgada.","inadmissível, seja em virtude da incidência de legislação ou de entendimento jurisprudencial do STF supervenientes, sob pena de ofensa à garantia constitucional da coisa julgada."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670518","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670518","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3932387","sourceQuestionId":"3932387","t":"cpc-m14","moduleId":"cpc-m14","q":"Com relação ao cumprimento de sentença, considere: I. O cumprimento da sentença não poderá ser promovido em face do fiador, do coobrigado ou do corresponsável que não tiver participado da fase de conhecimento. II. São títulos executivos judiciais, dentre outros, a sentença arbitral, a sentença estrangeira homologada pelo Superior Tribunal de Justiça e a decisão interlocutória estrangeira, após a concessão do exequátur à carta rogatória pelo Superior Tribunal de Justiça. III. No caso de condenação em quantia certa, o cumprimento definitivo da sentença far-se-á a requerimento do exequente, sendo o executado intimado para pagar o débito, no prazo máximo de cinco dias, acrescido de custas, se houver. Em conformidade com o Código de Processo Civil, está correto o que se afirma em","o":["III, apenas.","II e III, apenas.","I e II, apenas.","I e III, apenas.","I, II e III."],"a":2,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - ALegis (ALMS)/ALMS/Jurídico/2026 • TEC 3932387","source":"FCC - ALegis (ALMS)/ALMS/Jurídico/2026","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3932387","year":2026,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3062104","sourceQuestionId":"3062104","t":"cpc-m14","moduleId":"cpc-m14","q":"Considere as seguintes disposições do Código de Processo Civil: I. “Não impugnada a execução ou rejeitadas as arguições da executada, por ordem do juiz, dirigida à autoridade na pessoa de quem o ente público foi citado para o processo, o pagamento de obrigação de pequeno valor será realizado no prazo de 2 (dois) meses contado da entrega da requisição, mediante depósito na agência de banco oficial mais próxima da residência do exequente.” II. “Na ausência de normas que regulem processos eleitorais, trabalhistas ou administrativos, as disposições deste Código lhes serão aplicadas supletiva e subsidiariamente.” III. “Os Estados e o Distrito Federal poderão ajustar compromisso reciproco para prática de ato processual por seus procuradores em favor de outro ente federado, mediante convênio firmado pelas respectivas procuradorias.” IV. “A citação da União, dos Estados, do Distrito Federal, dos Municípios e de suas respectivas autarquias e fundações de direito público será realizada perante o órgão de Advocacia Pública responsável por sua representação judicial.” V. “Haverá repercussão geral sempre que o recurso impugnar acórdão que tenha reconhecido a inconstitucionalidade de tratado ou de lei federal í...].” Em conformidade com a jurisprudência do Supremo Tribunal Federal, é INCOMPATÍVEL coma Constituição Federal a disposição legal presente em","o":["IV, em relação a Estados, Distrito Federal e Municípios, por cercear o direito à ampla defesa dos entes federados e ofender sua capacidade de auto-organização e autonomia para definição das competências de seus respectivos órgãos de assessoria jurídica.","V, por estabelecer privilégio inconstitucional em favor da União, comparativamente aos demais entes federados, cabendo estendera presunção às leis estaduais, distritais e municipais.","II, no que se refere aos processos administrativos, no âmbito de Estados e Municípios, por cerceara capacidade de os entes federados se organizarem e estabelecerem ritos e regras para os respectivos processos administrativos, violando sua competência suplementar para legislar na matéria.","I, no que se refere à obrigatoriedade de realização do pagamento em banco oficial, por cerceara autonomia dos entes federados e configurar ofensa aos princípios da eficiência administrativa, da livre concorrência e da livre iniciativa.","III, por violara autonomia de Estados e Distrito Federal, quanto à forma de celebração de ajustes, bem como quanto à capacidade de disporem a respeito de seus órgãos de advocacia pública, cujos membros integram carreiras diversas, e não única, acessíveis mediante concursos públicos próprios, e não integrados."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3062104","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3062104","year":2024,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3986946","sourceQuestionId":"3986946","t":"cpc-m14","moduleId":"cpc-m14","q":"Em cumprimento de sentença de alimentos, a representante legal da criança promoveu a cobrança dos últimos 3 meses de alimentos vencidos e não pagos pelo pai. Sobre tal modalidade de cumprimento de sentença,","o":["o cumprimento da pena de prisão exime o executado do pagamento das prestações vencidas e não pagas no curso do processo.","a representante legal poderá propor o cumprimento de sentença pelo rito da penhora desde logo, caso em que não será admissível a prisão do executado.","o desconto dos alimentos diretamente em folha de pagamento dos rendimentos do executado só será cabível em relação aos alimentos vincendos.","a execução dos alimentos fixados em sentença não transitada em julgado, bem como dos definitivos, deve ser processadas em autos apartados.","o juiz poderá liminarmente decretar a prisão civil e determinar o protesto do pronunciamento judicial antes da intimação do executado."],"a":1,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026 • TEC 3986946","source":"FCC - Ana (MPE AL)/MPE AL/Jurídica/2026","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3986946","year":2026,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3079833","sourceQuestionId":"3079833","t":"cpc-m14","moduleId":"cpc-m14","q":"A respeito do regime constitucional de precatórios e requisições de pequeno valor decorrentes de condenação judicial, à luz da jurisprudência dominante do STF,","o":["é constitucional a expedição de ordem de pagamento de parcela incontroversa do crédito, na pendência de impugnação parcial ao cumprimento de sentença apresentada pela Fazenda Pública, sem que se cogite, fracionamento da requisição, desde que, para efeito de determinação do regime de pagamento do valor incontroverso (se precatório ou requisição de pequeno valor), seja observado o valor total da condenação, não sendo possível enquadrar a parcela incontroversa em requisição de pequeno valor quando o montante global ultrapassar o valor definido para as obrigações dessa natureza.","a prioridade no pagamento de que gozam os credores idosos, os portadores de doença grave e as pessoas com deficiência é transferida ao cessionário do precatório por ato oneroso, que se beneficiará do prazo reduzido do pagamento prioritário.","em se tratando de crédito decorrente de condenação genérica havida em ação coletiva para a proteção de direitos individuais homogêneos, a apresentação de cumprimentos individuais viola a regra que veda o fracionamento de precatórios em várias requisições de pequeno valor.","assim como se admite, em caso de litisconsórcio ativo, a expedição de uma requisição de pequeno valor para cada autor (condicionada à observação do limite máximo de valor adotado pelo respectivo ente público devedor), pode o advogado executar, também separadamente e por meio de várias requisições de pagamento, o valor total dos honorários sucumbenciais fixados, mesmo que o montante enseje, pela extensão, a expedição de precatório.","admite-se o fracionamento do valor relativo a honorários contratuais, para que estes sejam pagos por meio de requisição de pequeno valor, e o crédito principal, por meio de precatório."],"a":0,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079833","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079833","year":2024,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3296954","sourceQuestionId":"3296954","t":"cpc-m14","moduleId":"cpc-m14","q":"Jonas foi réu em ação de despejo por falta de pagamento. Na ação de conhecimento, Jonas foi citado pessoalmente e representado pela Defensoria Pública do Estado. A ação foi julgada totalmente procedente para ordenar o despejo, bem como para o pagamento das parcelas em atraso. Jonas desocupou o imóvel voluntariamente, porém não pagou o valor devido. O autor da ação, portanto, promoveu cumprimento de sentença em face de Jonas que deverá ser intimado a cumprir a sentença por","o":["oficial de Justiça.","aplicativo de mensagens ou qualquer outro meio eletrônico.","carta com aviso de recebimento.","edital.","diário de justiça, na pessoa do defensor público constituído nos autos."],"a":2,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025 • TEC 3296954","source":"FCC - AJ TRT6/TRT 6/Judiciária/Oficial de Justiça Avaliador/2025","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3296954","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373082","sourceQuestionId":"373082","t":"cpc-m14","moduleId":"cpc-m14","q":"No processo de execução e cumprimento de sentença,","o":["a exceção de pré-executividade, embora não prevista expressamente no novo Código de Processo Civil, é aceita pela doutrina e pela jurisprudência para que o executado se defenda mediante a alegação de matérias de ordem pública, cognoscíveis de ofício, de modo que é possível que, em uma execução fiscal, o executado alegue prescrição por meio de exceção de pré-executividade.","caso o executado já tenha apresentado embargos ou impugnação à execução, a desistência do exequente de toda a execução ou apenas alguma medida executiva dependerá do consentimento do embargante ou do impugnante.","a sentença que determina a inclusão de vantagem pecuniária em folha de pagamento de servidores públicos admite execução provisória, depois de confirmado em duplo grau necessário.","diante de uma sentença condenatória contra o Estado transitada em julgado e da superveniência de decisão do Supremo Tribunal Federal que julgou inconstitucional a lei que fundamentou a procedência do pedido nessa demanda, durante o cumprimento desta decisão, cabe ao ente, em sua defesa, ajuizar reclamação constitucional.","o cumprimento de sentença proferida contra a Fazenda Pública Estadual tem como única forma de satisfação a expedição de precatório."],"a":0,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/2016 • TEC 373082","source":"FCC - Proc (PGE MT)/PGE MT/2016","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373082","year":2016,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3297219","sourceQuestionId":"3297219","t":"cpc-m14","moduleId":"cpc-m14","q":"O efeito suspensivo da impugnação no cumprimento de sentença por quantia certa decorre de","o":["texto expresso de lei, como regra geral, o que impedirá a efetivação dos atos de substituição, de reforço ou de redução da penhora e de avaliação dos bens.","texto expresso de lei, como regra geral, abrangendo todos os aspectos da execução, ainda que somente parte do valor tenha sido impugnada.","texto expresso de lei, como regra geral, cabendo ao exequente requerer o prosseguimento da execução, oferecendo e prestando, nos próprios autos, caução suficiente e idônea a ser arbitrada pelo juiz.","requerimento do executado, desde que, como regra geral, haja garantia do juízo com penhora, caução ou depósitos suficientes, justificando que seus fundamentos são relevantes e que o prosseguimento da execução é manifestamente suscetível de causar grave dano de difícil ou incerta reparação.","requerimento do executado, o que impedirá a efetivação dos atos de substituição, de reforço ou de redução da penhora e de avaliação dos bens."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2025 • TEC 3297219","source":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3297219","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-271985","sourceQuestionId":"271985","t":"cpc-m14","moduleId":"cpc-m14","q":"NÃO são devidos honorários advocatícios","o":["nos embargos à execução.","nos processos em que a Fazenda Pública for vencedora.","no cumprimento de sentença, em qualquer hipótese, se já tiverem sido arbitrados na ação de conhecimento.","no Mandado de Segurança, ainda que o impetrante seja vencedor na impetração.","em nenhuma espécie de ação cautelar, porque eles serão arbitrados quando da prolação de sentença na ação de conhecimento."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JT TRT6/TRT 6/2015 • TEC 271985","source":"FCC - JT TRT6/TRT 6/2015","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/271985","year":2015,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3355417","sourceQuestionId":"3355417","t":"cpc-m14","moduleId":"cpc-m14","q":"Nilza, em atendimento na Defensoria Pública de São Paulo, relatou que o pai de sua filha está trabalhando com vínculo empregatício, porém não está pagando a pensão alimentícia fixada judicialmente. O inadimplemento é recente e a usuária manifestou desejo de que o cumprimento de sentença fosse ajuizado sob o rito da prisão. Ao elaborar o cumprimento de sentença, a Defensora Pública deverá indicar no polo passivo da demanda","o":["o pai e a empregadora, requerendo-se a expedição de ofício à empregadora para implementação de desconto das prestações alimentares futuras em folha de pagamento, bem como o parcelamento do débito, a ser descontado em folha de forma parcelada, desde que não ultrapasse sessenta por cento dos ganhos líquidos do genitor.","o pai e a empregadora, requerendo-se apenas a expedição de ofício à empregadora para implementação de desconto das prestações alimentares futuras em folha de pagamento.","apenas o pai, requerendo-se sua prisão civil como medida coercitiva ao pagamento do débito e somente o pedido de expedição de ofício à empregadora para implementação de desconto das prestações alimentares futuras em folha de pagamento.","apenas o pai, requerendo-se apenas sua prisão civil e demais medidas atípicas de execução como forma de coerção ao pagamento do débito.","apenas o pai, requerendo-se sua prisão civil como medida coercitiva ao pagamento do débito, bem como a expedição de ofício à empregadora para implementação de desconto das prestações alimentares futuras em folha de pagamento e do débito parcelado, desde que não ultrapasse cinquenta por cento de seus ganhos líquidos."],"a":4,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AnaDP (DPE SP)/DPE SP/2025 • TEC 3355417","source":"FCC - AnaDP (DPE SP)/DPE SP/2025","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3355417","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-331070","sourceQuestionId":"331070","t":"cpc-m14","moduleId":"cpc-m14","q":"De acordo com o Código de Processo Civil e com a jurisprudência dominante do Superior Tribunal de Justiça, em impugnação ao cumprimento de sentença líquida, se o executado alegar, como única matéria de defesa, excesso de execução, deverá","o":["apontar, na petição de impugnação, a parcela incontroversa do débito, bem como as incorreções do cálculo do credor, sob pena de rejeição liminar da impugnação, não se admitindo emenda à inicial.","requerer, na própria petição de impugnação, a realização de perícia, formulando quesitos e indicando assistente, sob pena de preclusão.","apontar, na petição de impugnação, a parcela incontroversa do débito, bem como as incorreções do cálculo do credor, sob pena de rejeição liminar da impugnação, admitindo-se, porém, emenda à inicial.","juntar, com a petição de impugnação, comprovante de depósito do valor integral em execução, sob pena de rejeição liminar da impugnação, não se admitindo emenda à inicial.","juntar, com a petição de impugnação, comprovante de depósito do valor incontroverso, sob pena de rejeição liminar da impugnação, admitindo-se, porém, emenda à inicial."],"a":0,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJSE/TJ SE/2015 • TEC 331070","source":"FCC - JE TJSE/TJ SE/2015","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/331070","year":2015,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3453282","sourceQuestionId":"3453282","t":"cpc-m14","moduleId":"cpc-m14","q":"Na impugnação ao cumprimento de sentença, o executado","o":["poderá alegar excesso de execução como único fundamento, ainda que sem indicar o valor que entende correto, requerendo-se a perícia contábil para demonstrativo de cálculo.","não poderá alegar incompetência relativa do juízo da execução, somente se admitindo como fundamento a alegação de incompetência absoluta.","não poderá apresentar impugnação que verse sobre eventual nulidade de citação na fase de conhecimento.","poderá alegar qualquer causa modificativa ou extintiva da obrigação, desde que supervenientes à sentença.","poderá alegar qualquer matéria de fato ou de direito em ampla cognição, desde que supervenientes à sentença."],"a":3,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025 • TEC 3453282","source":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3453282","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-373435","sourceQuestionId":"373435","t":"cpc-m14","moduleId":"cpc-m14","q":"Está de acordo com o entendimento sumular do Superior Tribunal de Justiça:","o":["São devidos honorários advocatícios no cumprimento de sentença, desde que haja impugnação, após escoado prazo para pagamento voluntário, que se inicia após a intimação do advogado da parte contrária.","É obrigatória ao juiz a reunião de execuções fiscais contra o mesmo devedor.","Em ação monitória fundada em cheque prescrito ajuizada contra o emitente, é indispensável a menção ao negócio jurídico subjacente à emissão da cártula.","No seguro de responsabilidade civil facultativo, é cabível o ajuizamento de ação pelo terceiro prejudicado, direta e exclusivamente em face da seguradora do apontado causador do dano.","Na hipótese de rejeição da impugnação ao cumprimento de sentença, não são cabíveis honorários advocatícios."],"a":4,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - JE TJPI/TJ PI/2015 • TEC 373435","source":"FCC - JE TJPI/TJ PI/2015","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Cumprimento da Sentença","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/373435","year":2015,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"Questão anterior à vigência plena do CPC/2015: preserve o gabarito histórico, mas confira a regra atual antes de memorizar.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3554467","sourceQuestionId":"3554467","t":"cpc-m14","moduleId":"cpc-m14","q":"Em conformidade com o Código de Processo Civil, o cumprimento de sentença","o":["que condene ao pagamento de prestação alimentícia é extinto pelo cumprimento da pena de prisão, que exime o executado do pagamento das prestações vencidas e vincendas.","somente pode ocorrer após o trânsito em julgado da sentença.","que condene ao pagamento de prestação alimentícia é extinto pelo cumprimento da pena de prisão, que exime o executado do pagamento das prestações vencidas, mas não das vincendas.","deve ser iniciado de oficio, caso a sentença haja condenado ao pagamento de quantia certa ou já fixada em liquidação.","será efetuado, em regra, perante o juízo que decidiu a causa no primeiro grau de jurisdição, podendo o exequente optar pelo juízo do atual domicilio do executado, pelo juízo do local onde se encontrem os bens sujeitos à execução ou pelo juízo do local onde deva ser executada a obrigação de fazer ou de não fazer, casos em que a remessa dos autos do processo será solicitada ao juízo de origem."],"a":4,"e":"Tema classificado no Módulo 14: Cumprimento de sentença e meios de impugnação. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025 • TEC 3554467","source":"FCC - Ana Min (MPE PI)/MPE PI/Processual/2025","subject":"Direito Processual Civil - Do Cumprimento da Sentença (arts. 513 a 538)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3554467","year":2025,"classificationReason":"Cumprimento de sentença expressamente previsto.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3379901","sourceQuestionId":"3379901","t":"cpc-m15","moduleId":"cpc-m15","q":"Para responder a questão, considere a Constituição Federal de 1988. Após reiteradas decisões sobre matéria constitucional e observado o objetivo previsto na Constituição Federal, o Supremo Tribunal Federal poderá,","o":["de ofício ou por provocação, mediante decisão de dois quintos dos seus membros, aprovar súmula que, a partir da sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal.","por provocação daqueles que podem propor a ação direta de inconstitucionalidade, mediante decisão de dois terços dos seus membros, aprovar súmula que, a partir da sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário, não possuindo, entretanto, efeito vinculante com relação à administração pública direta e indireta, tendo em vista a separação dos poderes.","de ofício ou por provocação, mediante decisão de metade dos seus membros, aprovar súmula que, a partir da sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário, sendo que do ato administrativo que contrariar a súmula aplicável caberá reclamação ao Supremo Tribunal Federal.","por provocação daqueles que podem propor a ação direta de inconstitucionalidade, mediante decisão de metade dos seus membros, aprovar súmula que, a partir da sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário, sendo que da decisão judicial que indevidamente aplicar a súmula caberá reclamação ao Supremo Tribunal Federal.","de ofício ou por provocação, mediante decisão de dois terços dos seus membros, aprovar súmula que, a partir da sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal."],"a":4,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025 • TEC 3379901","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025","subject":"Direito Constitucional (CF/1988 e Doutrina) - Das Súmulas Vinculantes (art. 103-A da CF/1988)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3379901","year":2025,"classificationReason":"Súmula vinculante expressamente prevista no bloco de recursos e precedentes.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3690947","sourceQuestionId":"3690947","t":"cpc-m15","moduleId":"cpc-m15","q":"Em relação à repercussão dos recursos repetitivos nos demais institutos e procedimentos no direito processual civil, considere: I. É possível o julgamento de improcedência liminar do pedido nas causas que dispensem a fase instrutória e cujo pedido contrarie acórdão proferido pelo Supremo Tribunal Federal ou pelo Superior Tribunal de Justiça em julgamento de recursos repetitivo. II. A sentença que estiver fundada em acórdão proferido pelo Supremo Tribunal Federal ou pelo Superior Tribunal de Justiça em julgamento de recursos repetitivos submete-se à remessa necessária. III. A caução no cumprimento de sentença poderá ser dispensada nos casos em que a sentença a ser provisoriamente cumprida estiver em conformidade com acórdão proferido no julgamento de casos repetitivos. IV. A alteração de tese jurídica adotada em julgamento de casos repetitivos poderá ser precedida de audiências públicas e da participação de pessoas, órgãos ou entidades que possam contribuir para a rediscussão da tese. V. A desistência do recurso impede a análise de questão que tiver sido objeto de julgamento de recursos extraordinários ou especiais repetitivos. De acordo com o Código de Processo Civil, está correto o que se afirma APENAS em","o":["II, IV e V.","I, III e IV.","I, II e III.","II, III e V.","I, IV e V."],"a":1,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (UNICAMP)/UNICAMP/2025 • TEC 3690947","source":"FCC - Proc (UNICAMP)/UNICAMP/2025","subject":"Direito Processual Civil - Dos Recursos para o STF e STJ (arts. 1.027 a 1.044)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3690947","year":2025,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3821673","sourceQuestionId":"3821673","t":"cpc-m15","moduleId":"cpc-m15","q":"No que concerne aos embargos de declaração, em conformidade com o Código de Processo Civil,","o":["somente se os embargos de declaração forem rejeitados, o recurso interposto pela outra parte antes da publicação do julgamento dos embargos de declaração será processado e julgado independentemente de ratificação.","caso o acolhimento dos embargos de declaração implique modificação da decisão embargada, o embargado que já tiver interposto outro recurso contra a decisão originária tem o direito de complementar ou alterar suas razões, nos exatos limites da modificação, no prazo de 15 dias, contado da intimação da decisão dos embargos de declaração.","os embargos de declaração serão opostos, no prazo de 5 dias, em petição dirigida ao juiz, com indicação do erro, obscuridade, contradição ou omissão, sujeitando-se a preparo, salvo se o embargante for beneficiário da justiça gratuita.","o juiz intimará o embargado para, querendo, manifestar-se, no prazo de 15 dias, sobre os embargos opostos, caso seu eventual acolhimento implique a modificação da decisão embargada.","consideram-se incluídos no acórdão os elementos que o embargante suscitou, para fins de pré-questionamento, salvo se os embargos de declaração forem inadmitidos ou rejeitados, caso o tribunal superior considere existentes erro, omissão, contradição ou obscuridade."],"a":1,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026 • TEC 3821673","source":"FCC - Ana GMQI (IPEM PE)/IPEM PE/Analista Jurídico/2026","subject":"Direito Processual Civil - Dos Embargos de Declaração (arts. 1.022 a 1.026)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3821673","year":2026,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3937738","sourceQuestionId":"3937738","t":"cpc-m15","moduleId":"cpc-m15","q":"Luana foi condenada, em primeira instância, a pagar indenização por danos morais e honorários advocatícios fixados em 10% sobre o valor da condenação. Ela interpôs apelação visando à reforma total da sentença. No entanto, o Tribunal de Justiça deu parcial provimento ao seu recurso apenas para alterar a data de início da correção monetária, o que representou uma alteração mínima no proveito econômico obtido com o julgamento. Nesse caso, de acordo com a jurisprudência do STJ acerca dos honorários advocatícios recursais,","o":["não haverá majoração dos honorários advocatícios, apenas se Luana tiver deferidos os benefícios da gratuidade da justiça.","haverá majoração dos honorários, de acordo com o trabalho adicional realizado pela outra parte, pois a alteração mínima no resultado equipara-se ao desprovimento do recurso.","haverá majoração dos honorários ao patamar máximo de 20%, tendo em vista que o recurso foi majoritariamente desprovido.","não haverá majoração dos honorários, pois houve parcial provimento do recurso, ainda que com mínima alteração no resultado do julgamento.","haverá majoração dos honorários, que poderão ultrapassar os 20%, pois o limite máximo fixado pelo CPC se restringe à condenação em primeira instância."],"a":3,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937738","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Recursos","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937738","year":2026,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3570040","sourceQuestionId":"3570040","t":"cpc-m15","moduleId":"cpc-m15","q":"A Emenda Constitucional 45/2004 instituiu o sistema de súmulas vinculantes pelo qual o Supremo Tribunal Federal poderá, de ofício ou por provocação, mediante decisão de dois terços dos seus membros, após reiteradas decisões sobre matéria constitucional, aprovar súmulas de efeito vinculante a partir de sua publicação no Diário Oficial. Nesse contexto, as súmulas vinculantes do Supremo Tribunal Federal","o":["não são consideradas fontes do Direito Processual do Trabalho e, portanto, não vinculam as decisões dos Tribunais que compõem a Justiça do Trabalho tendo em vista o princípio protetor que rege as relações de trabalho.","não são consideradas fontes do Direito Processual do Trabalho e não vinculam as decisões dos órgãos que compõem a Justiça do Trabalho em razão do princípio constitucional da dignidade humana.","são consideradas fontes subsidiárias do Direito Processual do Trabalho e vinculam apenas as decisões proferidas pelo Tribunal Superior do Trabalho.","são consideradas fontes diretas do Direito Processual do Trabalho e vinculam todos os órgãos que compõem a Justiça do Trabalho.","não são consideradas fontes do Direito Processual do Trabalho em razão da sua autonomia constitucional e, portanto, não possuem efeito vinculante em relação às decisões dos Tribunais que compõem a Justiça do Trabalho."],"a":3,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3570040","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Constitucional (CF/1988 e Doutrina) - Das Súmulas Vinculantes (art. 103-A da CF/1988)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3570040","year":2025,"classificationReason":"Súmula vinculante expressamente prevista no bloco de recursos e precedentes.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3079820","sourceQuestionId":"3079820","t":"cpc-m15","moduleId":"cpc-m15","q":"O Estado Sigma ajuizou ação, pelo rito comum, contra sociedade empresária com quem firmou contrato administrativo, visando a discussão de cláusulas e a restituição de parte dos valores pagos. O pedido é julgado improcedente em primeira instância, resultado mantido em grau recursal com o desprovimento, por votação unânime em julgamento colegiado, do recurso de apelação interposto pelo Estado. A solução da controvérsia tem como questão principal a interpretação de determinado dispositivo de lei federal, sendo certo que o Estado, em suas razões de apelação, apontou a existência de julgado da 10 Câmara do Tribunal Estadual local, que adotou a interpretação X — favorável à tese defendida pelo Estado; a 2a Câmara do mesmo Tribunal, ao manter a improcedência do pedido, optou pela interpretação Y, única outra possível juridicamente. Para buscar a reversão do resultado, e considerando descartada a possibilidade de interposição de embargos de declaração, a Procuradoria-Geral do Estado Sigma deverá","o":["“interpor agravo interno, a fim de provocar a manifestação de órgão superior do próprio Tribunal.","formular pedido de uniformização de interpretação de lei, para solução da discrepância de interpretação no âmbito interno do Tribunal.","manejar embargos de divergência, baseados na discrepância de interpretação da questão pelas Câmaras, a fim de esgotar as vias recursais ordinárias.","apresentar recurso extraordinário, com exclusividade por se tratar de matéria prejudicial, baseado na alegação de ofensa ao princípio constitucional da legalidade.","“interpor recurso especial, baseado na contrariedade à lei federal decorrente da adoção da interpretação Y."],"a":4,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079820","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Dos Recursos para o STF e STJ (arts. 1.027 a 1.044)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079820","year":2024,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"Lei 15.484/2026 disciplina a relevância da questão federal no REsp, com vigência a partir de 03/09/2026.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3937743","sourceQuestionId":"3937743","t":"cpc-m15","moduleId":"cpc-m15","q":"De acordo com o Código de Processo Civil, os embargos de declaração","o":["são cabíveis contra qualquer decisão judicial para corrigir erro material.","possuem efeito suspensivo e interrompem o prazo para interposição do recurso.","serão opostos no prazo de 15 dias e não se sujeitam a preparo.","não são cabíveis, caso seu eventual acolhimento implique a modificação da decisão embargada.","serão opostos no prazo de 5 dias e se sujeitam a preparo."],"a":0,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2026 • TEC 3937743","source":"FCC - DP MA/DPE MA/2026","subject":"Direito Processual Civil - Dos Embargos de Declaração (arts. 1.022 a 1.026)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3937743","year":2026,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3297224","sourceQuestionId":"3297224","t":"cpc-m15","moduleId":"cpc-m15","q":"Em ação de indenização proposta por Carla contra Flávio, o Juiz abriu prazo para especificação de provas. Carla postulou à julgamento antecipado do feito por não ter outras provas a apresentar. Flávio, contudo, pediu a oitiva de testemunhas e prova pericial. O Juiz, acolhendo o pedido de Carla, decidiu encerrar a instrução probatória e abriu prazo para alegações finais. Diante disso, em face da decisão, Flávio deverá","o":["impetrar mandado de segurança por ausência de previsão no Código de Processo Civil.","interpor agravo de instrumento por previsão taxativa no Código de Processo Civil.","ajuizar reclamação por se tratar de tema já decidido em sede de recurso repetitivo.","interpor agravo retido por previsão taxativa no Código de Processo Civil.","aguardar a prolação da sentença e, por ocasião da interposição de eventual apelação ou contrarrazões, alegar a questão em preliminar de recurso."],"a":4,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2025 • TEC 3297224","source":"FCC - AJ TRT6/TRT 6/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Recursos","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3297224","year":2025,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1646930","sourceQuestionId":"1646930","t":"cpc-m15","moduleId":"cpc-m15","q":"De acordo com o que estabelece a Constituição Federal, o Supremo Tribunal Federal poderá,","o":["de ofício ou por provocação, mediante decisão da maioria absoluta dos seus membros, após reiteradas decisões sobre matéria constitucional, aprovar súmula que, a partir de sua publicação na imprensa oficial, terá efeito vinculante exclusivamente em relação aos demais órgãos do Poder Judiciário.","de ofício ou por provocação, mediante decisão de maioria absoluta dos seus membros, após reiteradas decisões sobre matéria constitucional, aprovar súmula que, a partir de sua publicação na imprensa oficial, terá efeito vinculante em relação aos Poderes Legislativo, Executivo e Judiciário e à administração pública direta, nas esferas federal e estadual.","somente quando provocado, mediante decisão da maioria dos seus membros, aprovar súmula que, a partir de sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e do Poder Executivo, nas esferas federal e estadual.","de ofício ou por provocação, mediante decisão de dois terços dos seus membros, após reiteradas decisões sobre matéria constitucional, aprovar súmula que, a partir de sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e à administração pública direta e indireta, nas esferas federal, estadual e municipal.","somente de ofício, mediante decisão de dois terços dos seus membros, aprovar súmula que, a partir de sua publicação na imprensa oficial, terá efeito vinculante em relação aos demais órgãos do Poder Judiciário e, exclusivamente, à administração pública direta, nas esferas federal e estadual."],"a":3,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT11/TRT 11/Administrativa/\"Sem Especialidade\"/2024 • TEC 1646930","source":"FCC - TJ TRT11/TRT 11/Administrativa/\"Sem Especialidade\"/2024","subject":"Direito Constitucional (CF/1988 e Doutrina) - Das Súmulas Vinculantes (art. 103-A da CF/1988)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1646930","year":2024,"classificationReason":"Súmula vinculante expressamente prevista no bloco de recursos e precedentes.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3079837","sourceQuestionId":"3079837","t":"cpc-m15","moduleId":"cpc-m15","q":"Em relação aos atos dispositivos das partes:","o":["A desistência do mandado de segurança é possível apenas até a sentença, independentemente da anuência do legitimado passivo.","A desistência ou o abandono do processo impede o exame do mérito do Incidente de Resolução de Demandas Repetitivas.","Na desistência da execução não se exige a concordância do executado, independentemente da postura processual por ele adotada.","Citado o réu, a desistência da ação depende de seu consentimento.","O autor pode desistir da ação até a sentença, independentemente do consentimento do réu, se o STJ fixar tese contrária ao pedido em recurso repetitivo, mesmo que já apresentada contestação."],"a":4,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079837","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Dos Recursos para o STF e STJ (arts. 1.027 a 1.044)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079837","year":2024,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3679849","sourceQuestionId":"3679849","t":"cpc-m15","moduleId":"cpc-m15","q":"Sobre os embargos de declaração é correto afirmar:","o":["No âmbito da justiça estadual, lei local poderá estabelecer o valor do respectivo preparo.","Caso seu julgamento não altere a decisão embargada, o recurso interposto pela outra parte antes da publicação do julgamento dos embargos de declaração não depende de ratificação.","Caso seu acolhimento implique modificação da decisão embargada, a parte que já tiver interposto outro recurso contra a decisão originária tem o direito de complementar ou alterar suas razões livremente, no prazo de 15 dias.","Possuem efeito suspensivo, tanto assim que interrompem o prazo para a interposição de outros recursos.","Se considerados prequestionadores, o juiz ou o tribunal, em decisão fundamentada, condenará o embargante a pagar multa de até dois por cento sobre o valor atualizado da causa."],"a":1,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679849","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Dos Embargos de Declaração (arts. 1.022 a 1.026)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679849","year":2025,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-840076","sourceQuestionId":"840076","t":"cpc-m15","moduleId":"cpc-m15","q":"O réu de uma ação, em sua contestação, além de apresentar defesa direta de mérito, arguiu duas preliminares, uma delas alegando a incompetência absoluta do juiz, e a outra pedindo a decretação de segredo de justiça, considerando que nesta ação foram expostas questões de seu foro íntimo. Após a réplica, o juiz indeferiu ambos os pedidos. Tal decisão, de acordo com a sistemática do Código de Processo Civil de 2015 e em conformidade com o entendimento consolidado no âmbito do Superior Tribunal de Justiça, tem a natureza jurídica de decisão interlocutória,","o":["mas as hipóteses de indeferimento da alegação de incompetência absoluta e de segredo de justiça não estão previstas de forma expressa no rol taxativo do art. 1.015 do Código de Processo Civil, motivo pelo qual não admitem a interposição de agravo de instrumento e somente podem ser impugnadas oportunamente em preliminar de apelação.","e as hipóteses de indeferimento da alegação de incompetência absoluta e de segredo de justiça estão previstas de forma expressa no rol do art. 1.015 do Código de Processo Civil, de modo que ambas admitem a interposição de agravo de instrumento, sem qualquer esforço hermenêutico para além da interpretação literal dos dispositivos.","que versa sobre o mérito, hipótese prevista expressamente no rol do art. 1.015, inciso II, do Código de Processo Civil, de modo que admite a interposição de agravo de instrumento, independentemente do conteúdo desta decisão interlocutória.","e as hipóteses de indeferimento da alegação de incompetência absoluta e de segredo de justiça não estão previstas de forma expressa no rol do art. 1.015 do Código de Processo Civil; todavia, em razão da taxatividade mitigada, ambas as hipóteses atendem os requisitos firmados pela jurisprudência para admitir a interposição de agravo de instrumento.","mas somente a alegação da incompetência absoluta está prevista no rol do art. 1.015, do Código de Processo Civil, de modo que admite a interposição de agravo de instrumento; a decisão de indeferimento de segredo de justiça, embora não conste do referido rol, atende os requisitos firmados pela jurisprudência para admitir a interposição de agravo de instrumento, em razão da taxatividade mitigada."],"a":3,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP SP/DPE SP/2019 • TEC 840076","source":"FCC - DP SP/DPE SP/2019","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Recursos","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/840076","year":2019,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2872562","sourceQuestionId":"2872562","t":"cpc-m15","moduleId":"cpc-m15","q":"Acerca da súmula vinculante,","o":["o Supremo Tribunal Federal poderá, de ofício, mediante decisão da maioria de seus membros, após reiteradas decisões sobre matéria constitucional, aprovar súmula vinculante.","após a publicação na imprensa oficial, a súmula terá efeito vinculante em relação à Administração Pública, direta e indireta, nas esferas federal, estadual e municipal, em todos os Poderes da República.","caberá reclamação ao Supremo Tribunal Federal quanto a ato administrativo ou decisão judicial que contrariar súmula aplicável ou que indevidamente a aplicar.","a súmula terá por objetivo a validade, a interpretação e a eficácia de normas acerca das quais haja controvérsia atual de órgãos da Administração Pública entre si, a qual acarrete grave insegurança jurídica e relevante multiplicação de processos sobre questão idêntica.","a aprovação de súmula poderá ser provocada por qualquer cidadão, enquanto sua revisão ou cancelamento de súmula deverá ser provocada por aqueles que podem propor a ação direta de inconstitucionalidade."],"a":2,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Ag Ap (MPE AM)/MPE AM/Administrativo/2024 • TEC 2872562","source":"FCC - Ag Ap (MPE AM)/MPE AM/Administrativo/2024","subject":"Direito Constitucional (CF/1988 e Doutrina) - Das Súmulas Vinculantes (art. 103-A da CF/1988)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2872562","year":2024,"classificationReason":"Súmula vinculante expressamente prevista no bloco de recursos e precedentes.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3177399","sourceQuestionId":"3177399","t":"cpc-m15","moduleId":"cpc-m15","q":"Joana interpôs recurso extraordinário em face de acórdão do Tribunal de Justiça do Ceará. O recurso foi sobrestado pela Presidência do Tribunal, sob a justificativa de versava sobre controvérsia de caráter repetitivo ainda não decidida pelo Supremo Tribunal Federal. A decisão é","o":["irecorrivel.","recorrivel por agravo em Recurso Extraordinário.","recorrivel por Mandado de Segurança.","recorrivel por Agravo Interno.","recorrivel por Recurso Ordinário."],"a":3,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024 • TEC 3177399","source":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Dos Recursos para o STF e STJ (arts. 1.027 a 1.044)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3177399","year":2024,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2820218","sourceQuestionId":"2820218","t":"cpc-m15","moduleId":"cpc-m15","q":"Segundo o Código de Processo Civil, os embargos de declaração","o":["não admitem manifestação do embargado, devendo o juiz julgar o recurso no prazo de 5 dias.","possuem efeito suspensivo, motivo pelo qual suspendem o prazo para a interposição de outro recurso.","podem ser opostos independentemente de preparo contra decisão judicial que apresentar erro material, obscuridade, contradição ou omissão.","manifestamente protelatórios poderão ensejar a parte embargante condenação em multa de 20% sobre o valor atualizado da causa.","deverão ser opostos no prazo de 15 dias em petição dirigida ao juiz que proferiu a decisão."],"a":2,"e":"Tema classificado no Módulo 15: Recursos, precedentes, repercussão e repetitivos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023 • TEC 2820218","source":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023","subject":"Direito Processual Civil - Dos Embargos de Declaração (arts. 1.022 a 1.026)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2820218","year":2023,"classificationReason":"Recursos e precedentes expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883961","sourceQuestionId":"3883961","t":"cpc-m16","moduleId":"cpc-m16","q":"Após o rompimento de uma barragem de rejeitos de mineração, a Defensoria Pública firmou com a empresa responsável um Termo de Ajustamento de Conduta (TAC) de âmbito nacional. Uma das cláusulas do TAC previa o pagamento de uma indenização líquida e certa de R$ 50.000,00 a título de dano moral individual para cada morador que comprovasse residir na área diretamente atingida pela lama. Maria, uma das moradoras, tentou receber o valor administrativamente, mas a empresa negou o pagamento sob pretextos meramente protelatórios. Diante dessa situação e com base na jurisprudência do Superior Tribunal de Justiça, a medida judicial mais adequada e direta que a Defensoria Pública pode tomar em favor de Maria é","o":["notificar a empresa para que cumpra o TAC, sob pena de representação ao Ministério Público por crime de desobediência, sendo esta a única medida cabível antes da via judicial.","ajuizar uma Ação Civil Pública em nome de todos os moradores que tiveram o pagamento negado, pois o TAC só pode ser executado coletivamente pelo legitimado que o firmou.","ingressar com uma Ação Monitória, instruída com o TAC, para obter um mandado de pagamento, convertendo-o em título executivo judicial caso a empresa não pague ou não oponha embargos.","propor uma Ação de Execução de Título Extrajudicial em nome de Maria, utilizando o TAC como título executivo, para cobrar o valor líquido de R$ 50.000,00.","ajuizar uma nova Ação de Conhecimento em nome de Maria, pleiteando a condenação da empresa ao pagamento dos R$ 50.000,00, pois o TAC é apenas uma promessa de fato, que necessita de uma sentença para se tornar exigível."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883961","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Da Execução em Geral (arts. 771 a 796)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883961","year":2026,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883937","sourceQuestionId":"3883937","t":"cpc-m16","moduleId":"cpc-m16","q":"No que concerne aos procedimentos especiais e à execução de alimentos no Código de Processo Civil, está em conformidade com a legislação e a jurisprudência dominante:","o":["O juiz pode, de ofício e independentemente de requerimento da parte, converter o rito da prisão em rito da penhora se verificar que o executado não possui bens de fácil alienação.","A prisão civil por dívida de alimentos deve ser cumprida obrigatoriamente em regime fechado, ficando o preso separado dos presos comuns, pelo prazo de até seis meses.","O cumprimento de sentença que estabeleça obrigação de pagar alimentos que englobe parcelas atuais (até três prestações imediatamente anteriores ao ajuizamento) deve ocorrer necessariamente sob o rito de prisão, não sendo possível ao exequente dispor de tal medida.","É vedado o desconto em folha de pagamento de prestações alimentícias vencidas (débito pretérito), limitando-se a constrição apenas às parcelas vincendas mensais.","Caso existam concomitantemente débitos atuais e pretéritos, é possível a cumulação em um único procedimento de meios executivos de prisão e de penhora, desde que não ocorra tumulto processual."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883937","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Processo de Execução","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883937","year":2026,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-3670686","sourceQuestionId":"3670686","t":"cpc-m16","moduleId":"cpc-m16","q":"Sobre o processo de execução,","o":["quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo a ele mais proveitoso.","é nulo se o título executivo extrajudicial não corresponder a obrigação certa, líquida e exigível.","ao despachar a inicial, o juiz fixará honorários advocatícios de dez por cento, a serem pagos pelo executado, valor este que será reduzido pela metade se houver pagamento integral do débito no prazo de 15 (quinze) dias.","recaindo a penhora sobre bem imóvel, será intimado também o cônjuge do executado, salvo se forem casados em regime de comunhão parcial de bens.","a avaliação será feita pelo oficial de justiça, mesmo que uma das partes aceite a estimativa feita pela outra."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE MT)/PGE MT/IX/2025 • TEC 3670686","source":"FCC - Proc (PGE MT)/PGE MT/IX/2025","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3670686","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3883933","sourceQuestionId":"3883933","t":"cpc-m16","moduleId":"cpc-m16","q":"Em um cumprimento de sentença que determinou o pagamento de prestação alimentícia em que o(a) defensor(a) atua em favor do credor, após esgotadas as buscas típicas por bens nos sistemas informatizados disponíveis, o executado, que é empresário de sucesso mas não possui bens em nome próprio, continua inadimplente. A Defensoria requer a suspensão da CNH e do passaporte do devedor. De acordo com o Código de Processo Civil e a jurisprudência consolidada do STJ e STF, tais medidas atípicas","o":["devem ser aplicadas de forma automática sempre que houver o esgotamento das buscas de bens via sistemas conveniados ao Judiciário.","são vedadas em execuções de alimentos, pois a única medida coercitiva pessoal admitida pelo sistema é a prisão civil.","dependem de prévia alteração do título executivo judicial, sob pena de violação da coisa julgada.","são inconstitucionais por violarem o direito fundamental de ir e vir (liberdade de locomoção) do cidadão devedor.","podem ser deferidas em caráter subsidiário, desde que observados o contraditório e a proporcionalidade, e que haja indícios de que o devedor possui patrimônio oculto."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MT/DPE MT/2026 • TEC 3883933","source":"FCC - DP MT/DPE MT/2026","subject":"Direito Processual Civil - Da Execução de Alimentos (arts. 911 a 913)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3883933","year":2026,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-662314","sourceQuestionId":"662314","t":"cpc-m16","moduleId":"cpc-m16","q":"Nas demandas contra a Fazenda Pública, à luz das disposições do Código de Processo Civil,","o":["a execução de sentença condenatória deve ser feita em procedimento autônomo, citando a Fazenda para a oposição de embargos.","embora o trânsito em julgado não seja requisito legal para início do cumprimento de sentença, por força da Constituição antes dele não é possível expedir ordem de precatório ou requisição de pagamento de pequeno valor mesmo que se trate de verba de natureza alimentar.","caso a Fazenda seja intimada para pagar o débito, no prazo de quinze dias, e não realize pagamento voluntário no prazo, o débito será acrescido de multa de dez por cento e, também, de honorários de advogado de dez por cento.","não impugnada a execução ou rejeitadas as arguições da executada, o próprio juiz da causa expedirá precatório em favor do exequente.","no processo de conhecimento pelo procedimento comum, o prazo para resposta da Fazenda Pública deve ser contado em quádruplo, razão pela qual o prazo para contestação é de sessenta dias."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP AM/DPE AM/2018 • TEC 662314","source":"FCC - DP AM/DPE AM/2018","subject":"Direito Processual Civil - Da Execução Contra a Fazenda Pública (art. 910)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/662314","year":2018,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3126685","sourceQuestionId":"3126685","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o Código de Processo Civil, na execução para entrega de coisa certa,","o":["pode o executado, em embargos à execução, alegar retenção apenas por benfeitorias necessárias.","constada a perda ou deterioração da coisa, os prejuízos deverão ser apurados em ação autônoma, pelo procedimento comum.","alienada a coisa quando já litigiosa, o juiz ouvirá o terceiro adquirente e depois decidirá sobre sua entrega.","pode o executado, em embargos à execução, alegar retenção por benfeitorias necessárias ou úteis.","o devedor será citado para satisfazer a obrigação ou depositar o equivalente em dinheiro, sob pena de multa de 10% sobre o valor estimado da obrigação."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024 • TEC 3126685","source":"FCC - Proc (J Guararapes)/Pref J Guararapes/2024","subject":"Direito Processual Civil - Da Execução Para a Entrega de Coisa (arts. 806 a 813)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3126685","year":2024,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3570055","sourceQuestionId":"3570055","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o Código de Processo Civil, na execução da obrigação de fazer,","o":["o executado será citado para satisfazê-la no prazo de 5 dias, ainda que outro conste do título executivo.","é incabível a fixação de astreintes se estas não tiverem sido previstas no título executivo.","o juiz, ao despachar a inicial, fixará multa por atraso no cumprimento, a qual não poderá ser reduzida se tiver constado do título executivo.","o executado será citado para satisfazê-la no prazo de 15 dias, ainda que outro conste do título executivo.","se o executado não satisfizer a obrigação, pode o exequente, nos próprios autos do processo, requerer a satisfação da obrigação à custa do executado ou pedir perdas e danos."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3570055","source":"FCC - AJ TRT2/TRT 2/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Execução das Obrigações de Fazer ou de Não Fazer (arts. 814 a 823)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3570055","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3453279","sourceQuestionId":"3453279","t":"cpc-m16","moduleId":"cpc-m16","q":"É considerada fraude à execução a alienação de bem sobre o qual","o":["pender ação de natureza condenatória fundada em direito pessoal ou real, desde que a pendência do processo tenha sido averbada no respectivo registro público, se houver.","tramitava ação contra o devedor capaz de levá-lo à insolvência, ainda que iniciada posteriormente à alienação ou à oneração do bem.","tramitava contra o devedor ação de execução, independentemente da averbação do processo no registro público.","tramitava contra o devedor ação de conhecimento, independentemente do valor da causa, ao tempo da alienação do bem.","pender ação fundada em direito real ou com pretensão reipersecutória, desde que a pendência do processo tenha sido averbada no respectivo registro público, se houver."],"a":4,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025 • TEC 3453279","source":"FCC - AJ TRT1/TRT 1/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Execução em Geral (arts. 771 a 796)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3453279","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3375449","sourceQuestionId":"3375449","t":"cpc-m16","moduleId":"cpc-m16","q":"A respeito do regime jurídico aplicável ao processo de execução, considere as seguintes assertivas: I. É ônus do executado provar que a pequena propriedade rural é explorada pela família para fins de reconhecimento de sua impenhorabilidade. II. A penhora de faturamento poderá ser deferida após a demonstração da inexistência dos bens classificados em posição superior na ordem preferencial de bens passíveis de constrição judicial ou, alternativamente, se houver constatação, pelo juiz, de que tais bens são de difícil alienação. III. A impenhorabilidade de quantia inferior a quarenta salários mínimos depositada em caderneta de poupança é matéria de ordem pública, podendo ser reconhecida de ofício pelo juiz. IV. Considera-se provada a ocorrência de fraude à execução nos casos em que a transferência da propriedade de bem imóvel pertencente ao executado a um terceiro ocorrer em momento anterior ao da averbação de penhora na respectiva matrícula. Está correto o que se afirma APENAS em:","o":["II e IV.","III e IV.","II e III.","I e II.","I e III."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP RS/DPE RS/2025 • TEC 3375449","source":"FCC - DP RS/DPE RS/2025","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Processo de Execução","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3375449","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2296264","sourceQuestionId":"2296264","t":"cpc-m16","moduleId":"cpc-m16","q":"De acordo com o que estabelece o Código de Processo Civil sobre o processo de execução,","o":["verificando que a petição inicial da execução está incompleta ou que não está acompanhada dos documentos indispensáveis à propositura da execução, o juiz determinará que o exequente a corrija, no prazo de 5 dias, sob pena de indeferimento.","a nulidade da execução somente será pronunciada pelo juiz, a requerimento da parte, mediante a apresentação de embargos à execução.","quando por vários meios o exequente puder promover a execução, o juiz mandará que se faça pelo modo mais gravoso para o executado.","ao propor a execução, incumbe ao exequente indicar a espécie de execução de sua preferência, quando por mais de um modo puder ser realizada.","nas obrigações alternativas, quando a escolha couber ao credor, esse será citado para exercer a opção e realizar a prestação dentro de 10 dias, se outro prazo não lhe foi determinado em lei ou em contrato."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT5/TRT 5/Judiciária/\"Sem Especialidade\"/2022 • TEC 2296264","source":"FCC - AJ TRT5/TRT 5/Judiciária/\"Sem Especialidade\"/2022","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2296264","year":2022,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1005260","sourceQuestionId":"1005260","t":"cpc-m16","moduleId":"cpc-m16","q":"Com respeito à execução da prestação alimentícia, considere: I. Na execução fundada em título executivo extrajudicial que contenha obrigação alimentar, o juiz mandará intimar o executado para, em 3 (três) dias, efetuar o pagamento das parcelas anteriores ao início da execução e das que se vencerem no seu curso, provar que o fez ou justificar a impossibilidade de fazê-lo. II. O débito alimentar que autoriza a prisão civil do alimentante é o que compreende as três prestações anteriores ao ajuizamento da execução e as que se vencerem no curso do processo. III. O cancelamento de pensão alimentícia de filho que atingiu a maioridade está sujeito à decisão judicial, mediante contraditório, ainda que nos próprios autos em que houver sido concedida. IV. Os efeitos da sentença que reduz, majora ou exonera o alimentante do pagamento retroagem à data do vencimento de cada parcela, defesas a repetibilidade e a compensação. Está correto o que se afirma APENAS em","o":["I e IV.","III e IV.","I, II e III.","II e III.","II, III e IV."],"a":3,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Prom Jus (MPE MT)/MPE MT/2019 • TEC 1005260","source":"FCC - Prom Jus (MPE MT)/MPE MT/2019","subject":"Direito Processual Civil - Da Execução de Alimentos (arts. 911 a 913)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1005260","year":2019,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"Lei 15.479/2026 criou transferência automática de alimentos, mas só entra em vigor em 30/07/2027.","auditStatus":"gabarito-historico-com-alerta"},{"id":"fcc-cpc-719796","sourceQuestionId":"719796","t":"cpc-m16","moduleId":"cpc-m16","q":"No tocante à execução contra a Fazenda Pública, é correto afirmar:","o":["A Fazenda Pública será intimada para opor embargos em trinta dias.","Não é cabível ação monitória contra a Fazenda Pública.","É cabível execução por título extrajudicial contra a Fazenda Pública.","Não opostos embargos, expedir-se-á precatório em favor do exequente, para pagamento imediato, qualquer que seja o valor exigido judicialmente por ele, haja vista o regime jurídico especial previsto em favor do ente fazendário.","Ao embargar, a Fazenda Pública só poderá alegar questões preliminares prejudiciais e, no mérito, pagamento ou compensação creditícia."],"a":2,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018 • TEC 719796","source":"FCC - AFRE (SEF SC)/SEF SC/Gestão Tributária/2018","subject":"Direito Processual Civil - Da Execução Contra a Fazenda Pública (art. 910)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/719796","year":2018,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3679844","sourceQuestionId":"3679844","t":"cpc-m16","moduleId":"cpc-m16","q":"Considere as assertivas abaixo acerca da fraude à execução: I. A alienação fraudulenta é nula em relação ao exequente. II. Nos casos de desconsideração da personalidade jurídica, a fraude verifica-se a partir da citação da parte cuja personalidade se pretende desconsiderar. III. Seu reconhecimento ocorre nos autos do processo de execução, dispensada a intimação do terceiro adquirente. IV. Caracteriza-se, dentre outros casos, quando realizada a alienação de bem na pendência de processo de execução, cuja admissão conste de certidão averbada junto ao registro desse mesmo bem. Está correto o que se afirma APENAS em","o":["II e III.","II e IV.","III e IV.","I e II.","I e III."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679844","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Da Execução em Geral (arts. 771 a 796)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679844","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3542692","sourceQuestionId":"3542692","t":"cpc-m16","moduleId":"cpc-m16","q":"Em ação indenizatória em fase de cumprimento definitivo de sentença, foi comunicada a cessão do crédito executado, requerendo-se a substituição processual do exequente (cedente) pelo cessionário do crédito. Nesse caso, de acordo com o entendimento firmado pelo Superior Tribunal de Justiça no julgamento de tema repetitivo, essa substituição processual","o":["depende da autorização ou consentimento do devedor, que poderá ser tácito, caso não seja manifestada oportuna oposição.","dispensa a autorização ou o consentimento do devedor.","depende da autorização ou consentimento do devedor, que necessariamente deverão ser expressos.","depende da autorização ou consentimento do devedor, que poderão, no entanto, ser supridos pelo juiz se houver justo motivo.","deverá ser indeferida, ainda que conte com a autorização ou consentimento do devedor."],"a":1,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025 • TEC 3542692","source":"FCC - AJ TRF4/TRF 4/Judiciária/\"Sem Especialidade\"/2025","subject":"Direito Processual Civil - Jurisprudência dos Tribunais Superiores sobre Processo de Execução","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3542692","year":2025,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-348443","sourceQuestionId":"348443","t":"cpc-m16","moduleId":"cpc-m16","q":"Manoel e Matias firmaram um contrato de compra e venda evolvendo obrigação alternativa, cuja escolha para realização da prestação caberá ao devedor Matias. Inadimplido o contrato, Manoel ajuíza ação de execução de título extrajudicial contra Matias. Matias será, então, citado para, em regra, exercer a opção e realizar a prestação dentro de","o":["10 dias.","15 dias.","30 dias.","20 dias.","5 dias."],"a":0,"e":"Tema classificado no Módulo 16: Execução: princípios, títulos, obrigações e Fazenda Pública. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - TJ TRT14/TRT 14/Administrativa/2016 • TEC 348443","source":"FCC - TJ TRT14/TRT 14/Administrativa/2016","subject":"Direito Processual Civil - Disposições Gerais (arts. 797 a 805)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/348443","year":2016,"classificationReason":"Princípios ou espécie de execução expressamente prevista.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3956211","sourceQuestionId":"3956211","t":"cpc-m17","moduleId":"cpc-m17","q":"Em uma ação de cobrança, Joana, fictamente citada, remanesceu revel, sendo-lhe nomeado defensor público para exercer as funções de curador especial. Na fase de cumprimento de sentença, foi realizada a penhora de bem imóvel de sua propriedade. À luz do Código de Processo Civil e da jurisprudência do STJ, a intimação da penhora","o":["é dispensada nos casos em que o executado tenha sido fictamente citado na fase de conhecimento, eis que se trata de ato processual de que não se exige ciência do executado citado fictamente que tenha restado revel.","deve ser realizada exclusivamente na pessoa do curador especial, uma vez que a intimação pessoal é prerrogativa institucional da Defensoria Pública, sendo inválida eventual intimação direta do executado citado por edital, em razão da inexistência de vínculo direto com o processo.","deve ser realizada pessoalmente ao executado, ainda que citado por edital na fase de conhecimento, não sendo suprida pela intimação pessoal do curador especial, que não se equipara a advogado constituído.","deve ser realizada exclusivamente na pessoa do curador especial, cabendo como matéria de defesa ao executado a alegação de inexigibilidade da obrigação ou eventual excesso de execução, a ser formulada por meio de exceção de pré-executividade.","na pessoa do curador especial é considerada válida, desde que feita pessoalmente ao Defensor Público e que não seja demonstrado prejuízo ao executado, aplicando-se o consagrado princípio da instrumentalidade das formas."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP BA/DPE BA/2026 • TEC 3956211","source":"FCC - DP BA/DPE BA/2026","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3956211","year":2026,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3679846","sourceQuestionId":"3679846","t":"cpc-m17","moduleId":"cpc-m17","q":"Sobre as defesas do executado é correto afirmar:","o":["Os embargos à execução serão oferecidos no prazo de 15 dias, que serão contados individualmente no caso de litisconsórcio passivo, a partir da juntada aos autos do respectivo comprovante de citação.","Não cabe a rejeição liminar dos embargos em razão de julgamento liminar de improcedência do pedido.","A possibilidade de impugnação não se aplica ao cumprimento provisório de sentença.","A impugnação ao cumprimento de sentença apresentada pela Fazenda Pública não exige a expressa indicação do valor, considerado o devido, porque é dispensada a apresentação de memória de cálculo demonstrativa do excesso alegado, por força do interesse público envolvido.","O prazo de 15 dias para apresentação de impugnação ao cumprimento de sentença conta-se da intimação do devedor para pagamento do débito, fluindo ambos os prazos simultaneamente."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE TO)/PGE TO/2025 • TEC 3679846","source":"FCC - Proc (PGE TO)/PGE TO/2025","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3679846","year":2025,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2022859","sourceQuestionId":"2022859","t":"cpc-m17","moduleId":"cpc-m17","q":"A respeito da execução e temas correlatos,","o":["o termo inicial da prescrição no curso do processo será a ciência da primeira tentativa infrutífera de localização do devedor ou de bens penhoráveis, sendo ela passível de suspensão, por uma única vez, pelo prazo máximo de um ano.","a prescrição no curso do processo só poderá ser reconhecida se arguida pelo devedor ou terceiro interessado.","não serão praticados atos processuais de qualquer natureza, uma vez suspensa a execução.","se for conveniente às partes, o juiz declarará suspensa a execução durante o prazo máximo de 90 dias, a fim de que obtenham solução consensual para cumprimento da obrigação.","a execução suspensa em razão do oferecimento de embargos de devedor poderá prosseguir, inclusive com a prática de atos de expropriação, se oferecida caução pelo credor."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE AM)/PGE AM/2022 • TEC 2022859","source":"FCC - Proc (PGE AM)/PGE AM/2022","subject":"Direito Processual Civil - Da Suspensão e da Extinção do Processo de Execução (arts. 921 a 925)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2022859","year":2022,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3380062","sourceQuestionId":"3380062","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, a execução por quantia certa realiza-se pela expropriação de bens do executado, consistente em:","o":["alienação em leilão, somente.","adjudicação, alienação e apropriação de frutos e rendimentos de empresa ou de estabelecimentos e de outros bens.","adjudicação, comissão, leilão e praceamento.","praceamento e comissão, somente.","leilão, venda direta e desapropriação, somente."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025 • TEC 3380062","source":"FCC - AJ TRT15/TRT 15/Judiciária/Sem Especialidade/2025","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3380062","year":2025,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3177393","sourceQuestionId":"3177393","t":"cpc-m17","moduleId":"cpc-m17","q":"Ulisses foi citado em ação de execução em razão do inadimplemento de divida constante de documento particular assinado pelo devedor e por duas testemunhas. Ulisses reconhece a divida, porém entende que o valor pleiteado estão superior ao devido no título. Nesse caso, Ulisses deverá opor embargos à execução","o":["mediante depósito prévio Integral do valor da causa indicado pelo exequente, sendo 30% no ato da petição Inicial e o restante com parcelamento em até 6 vezes.","mediante depósito prévio integral do valor da causa indicado pelo exequente.","independentemente de depósito prévio, porém devera declarar na petição inicial o valor que entende correto.","mediante depósito prévio de 30% do valor da causa indicado pelo exequente.","mediante depósito prévio do valor que entende correto."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024 • TEC 3177393","source":"FCC - AJ TRT7/TRT 7/Judiciária/\"Sem Especialidade\"/2024","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3177393","year":2024,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3451258","sourceQuestionId":"3451258","t":"cpc-m17","moduleId":"cpc-m17","q":"Considere o Código de Processo Civil brasileiro para responder à questão. Quando realizada a penhora de um bem imóvel em processo de execução, sua avaliação, quando não forem necessários conhecimentos especializados, será realizada, em regra,","o":["pelo Oficial de Justiça.","por avaliador nomeado pelo Juiz.","pela parte exequente.","pela parte executada.","por perito nomeado pelo Juiz."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025 • TEC 3451258","source":"FCC - AJ TRT1/TRT 1/Judiciária/Oficial de Justiça Avaliador Federal/2025","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3451258","year":2025,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3227499","sourceQuestionId":"3227499","t":"cpc-m17","moduleId":"cpc-m17","q":"Analise as proposições abaixo, acerca dos embargos à execução: I. Os embargos à execução possuem natureza de defesa & devem ser opostos nos próprios autos da execução. II. Os embargos à execução podem ser opostos independentemente do oferecimento de penhora, depósito ou caução. III. Quando há mais de um executado o prazo para embargar conta-se sempre da juntada aos autos do último comprovante de citação. IV. Nos embargos à execução, o executado poderá alegar qualquer matéria que lhe seria lícito alegar como defesa em processo de conhecimento. De acordo com o Código de Processo Civil, está coreto o que se afirma APENAS em","o":["I e II.","III e IV.","Il e IV.","I e III.","II e III"],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3227499","source":"FCC - AJ TRT20/TRT 20/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3227499","year":2024,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3079821","sourceQuestionId":"3079821","t":"cpc-m17","moduleId":"cpc-m17","q":"Em relação à fase expropriatória do processo de execução,","o":["o exequente, que tem legitimidade para adjudicar o bem penhorado, não pode oferecer lance em leilão judicial, salvo se igual ou superior ao valor da avaliação.","a ampliação da penhora só é cabível após a tentativa de alienação judicial do bem penhorado.","sendo devedor partido político, são penhoráveis os recursos recebidos do fundo partidário.","o seguro de garantia judicial não equivale a dinheiro para fins de substituição da penhora, salvo se contratado em valor não inferior ao do débito exequendo, acrescido de 30%.","a impenhorabilidade dos valores depositados em caderneta de poupança não é oponível em ação de execução de obrigação alimentar, desde que esta seja decorrente de parentesco."],"a":3,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (PGE GO)/PGE GO/2024 • TEC 3079821","source":"FCC - Proc (PGE GO)/PGE GO/2024","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3079821","year":2024,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-1234850","sourceQuestionId":"1234850","t":"cpc-m17","moduleId":"cpc-m17","q":"No que se refere aos embargos à execução, a legislação vigente estabelece que:","o":["se a eles for concedido efeito suspensivo, isto não obstará a efetivação dos atos de substituição, de reforço ou de redução da penhora e de avaliação de bens.","se destinam a desconstituir a sentença que formou título para seu cumprimento.","dependem de garantia real ou fidejussória ao juízo para serem opostos.","permitem o parcelamento do débito, em até seis vezes, sem prejuízo da discussão sobre sua existência.","terão efeito suspensivo como regra geral, pela possibilidade de dano grave e irreparável futuro ao devedor."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Adv Leg (ALAP)/ALAP/Atividade de Serviços Jurídicos/Procurador/2020 • TEC 1234850","source":"FCC - Adv Leg (ALAP)/ALAP/Atividade de Serviços Jurídicos/Procurador/2020","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/1234850","year":2020,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-3678193","sourceQuestionId":"3678193","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, em se tratando de divida não alimentar, é(são) penhorável(eis)","o":["os frutos e os rendimentos dos bens inalienáveis, à falta de outros bens penhoráveis do executado.","os honorários de profissional liberal.","os bens móveis úteis ao exercício da profissão do executado.","o seguro de vida do executado.","a quantia inferior a 40 salários-mínimos depositada em caderneta de poupança."],"a":0,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024 • TEC 3678193","source":"FCC - AJ TRT7/TRT 7/Judiciária/Oficial de Justiça Avaliador Federal/2024","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/3678193","year":2024,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-739849","sourceQuestionId":"739849","t":"cpc-m17","moduleId":"cpc-m17","q":"Paulo e Roberto são demandados em uma ação de execução de título extrajudicial. Paulo, foi citado em 5 de novembro, e Roberto foi citado no dia 09 do mesmo mês. Paulo, sem que tenha assegurado o juízo, apresentou embargos à execução, alegando somente excesso de execução. Nesse caso, o início do prazo para os embargos é contado","o":["a partir da juntada do último comprovante de citação; os embargos de Paulo serão liminarmente rejeitados caso ele não tenha apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizado do seu cálculo.","separadamente para os executados, a partir da juntada do respectivo comprovante de citação; os embargos de Paulo serão liminarmente rejeitados em razão de não ter assegurado o juízo.","separadamente para os executados, a partir da juntada do respectivo comprovante de citação; os embargos de Paulo serão liminarmente rejeitados caso ele não tenha apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizadodo seu cálculo.","a partir da juntada do último comprovante de citação; os embargos de Paulo serão liminarmente rejeitados em razão de não ter assegurado o juízo.","a partir da juntada do último comprovante de citação; os embargos de Paulo devem ser conhecidos apesar de não ter assegurado o juízo ou apresentado na petição o valor que entende correto e o demonstrativo discriminado e atualizado do seu cálculo, pois tais requisitos não são exigidos por lei."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - DP MA/DPE MA/2018 • TEC 739849","source":"FCC - DP MA/DPE MA/2018","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/739849","year":2018,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2819722","sourceQuestionId":"2819722","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, impenhorável","o":["o rendimento do bem inalienável em qualquer caso.","o seguro de vida.","o bem móvel que serve apenas para adornar escritório profissional.","o pertence de elevado valor de uso pessoal do executado.","a pequena propriedade rural, assim definida em lei, ainda que ociosa."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT12/TRT 12/Judiciária/\"Sem Especialidade\"/2023 • TEC 2819722","source":"FCC - AJ TRT12/TRT 12/Judiciária/\"Sem Especialidade\"/2023","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2819722","year":2023,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-583664","sourceQuestionId":"583664","t":"cpc-m17","moduleId":"cpc-m17","q":"Anderson ajuizou ação de execução de título extrajudicial contra Paulo e seu irmão Renato, que foram regularmente citados pelo correio, sendo que o Aviso de Recebimento − A.R. da carta de citação entregue a Paulo foi juntado aos autos no dia 02/08/2017 e o A.R. da carta de citação entregue a Renato foi juntado aos autos em 08/08/2017. Nesse caso, considerando que os executados são representados por advogados distintos, o prazo para Paulo opor embargos à execução","o":["será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da sua própria carta de citação.","não será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da sua própria carta de citação.","será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da carta de citação de Renato.","não será contado em dobro, considerando-se dia do começo a data da juntada aos autos do aviso de recebimento da carta de citação de Renato.","será contado em dobro, considerando-se dia do começo a data em que recebida a carta de citação, independentemente da data da juntada aos autos do respectivo aviso de recebimento."],"a":1,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017 • TEC 583664","source":"FCC - AJ TRF5/TRF 5/Judiciária/\"Sem Especialidade\"/2017","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/583664","year":2017,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-2820216","sourceQuestionId":"2820216","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, em caso de penhora de bens, o Oficial de Justiça realizará a avaliação quando","o":["houver bens que demandem conhecimentos especializados para avaliação, ainda que diante de execução que comporte a realização de avaliação específica por profissional indicado pelo juiz.","se tratar de títulos da dívida pública, de ações de sociedades e de títulos de crédito negociáveis em bolsa.","se tratar de títulos ou de mercadorias que tenham cotação em bolsa, ainda que haja comprovação por certidão ou publicação no órgão oficial.","se tratar de veículos automotores ou de outros bens cujo preço médio de mercado possa ser conhecido por meio de pesquisas realizadas por órgãos oficiais.","houver fundada dúvida do juiz quanto ao real valor do bem, no caso de uma das partes aceitar a estimativa feita pela outra."],"a":4,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023 • TEC 2820216","source":"FCC - AJ TRT12/TRT 12/Judiciária/Oficial de Justiça Avaliador Federal/2023","subject":"Direito Processual Civil - Da Execução Por Quantia Certa (arts. 824 a 909)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/2820216","year":2023,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"},{"id":"fcc-cpc-337498","sourceQuestionId":"337498","t":"cpc-m17","moduleId":"cpc-m17","q":"De acordo com o Código de Processo Civil, os embargos do devedor serão","o":["recebidos, em regra, no efeito suspensivo, o qual poderá ser revogado a qualquer tempo, se o credor prestar caução idônea a compensar eventuais prejuízos que o devedor venha a sofrer com os atos expropriatórios.","oferecidos no prazo de 15 dias, contados da data em que o devedor receber o mandado de citação.","rejeitados liminarmente quando manifestamente protelatórios, dispensada, nesse caso, a prévia manifestação do exequente.","rejeitados liminarmente quando manifestamente protelatórios, caso em que o juiz imporá, em favor do Estado, multa em valor não superior a 10% do valor em execução.","recebidos, em regra, sem efeito suspensivo, o qual poderá ser concedido, independentemente de garantia da execução ou de outros requisitos, se relevantes os fundamentos dos embargos."],"a":2,"e":"Tema classificado no Módulo 17: Execução por quantia, penhora, expropriação e embargos. Revise a teoria e a leitura esquematizada deste módulo.","r":"FCC - Proc (São Luís)/Pref São Luís/2016 • TEC 337498","source":"FCC - Proc (São Luís)/Pref São Luís/2016","subject":"Direito Processual Civil - Dos Embargos à Execução (arts. 914 a 920)","real":true,"bank":"FCC","bankLabel":"QUESTÃO REAL FCC","url":"https://www.tecconcursos.com.br/questoes/337498","year":2016,"classificationReason":"Execução por quantia, embargos ou suspensão expressamente previstos.","update":"","auditStatus":"gabarito-preservado-e-classificado"}]);
